import { useState, useEffect } from 'react'

const ACCIONES_DEFAULT = [
  { symbol: 'EC', nombre: 'Ecopetrol', icono: '🛢️', pais: 'Colombia' },
  { symbol: 'CIB', nombre: 'Bancolombia', icono: '🏦', pais: 'Colombia' },
  { symbol: 'NU', nombre: 'Nubank', icono: '💜', pais: 'Brasil / Colombia' },
  { symbol: 'BBVA', nombre: 'BBVA', icono: '🔵', pais: 'España / Colombia' },
  { symbol: 'GEB', nombre: 'Grupo Energía Bogotá', icono: '⚡', pais: 'Colombia' },
]

const TRM_DEFAULT = 4200

const metricasDetalle = (accion, formatCOP) => [
  {
    label: 'Precio actual',
    valor: `$${accion.precio.toFixed(2)} USD`,
    apoyo: formatCOP(accion.precio),
  },
  {
    label: 'Máximo del día',
    valor: `$${accion.maximo.toFixed(2)} USD`,
    apoyo: formatCOP(accion.maximo),
  },
  {
    label: 'Mínimo del día',
    valor: `$${accion.minimo.toFixed(2)} USD`,
    apoyo: formatCOP(accion.minimo),
  },
  {
    label: 'Apertura',
    valor: `$${accion.apertura.toFixed(2)} USD`,
    apoyo: formatCOP(accion.apertura),
  },
  {
    label: 'Cierre anterior',
    valor: `$${accion.cierreAnt.toFixed(2)} USD`,
    apoyo: formatCOP(accion.cierreAnt),
  },
  {
    label: 'Variación',
    valor: `${accion.subio ? '+' : ''}${accion.cambio.toFixed(2)} USD`,
    apoyo: `${accion.porcentaje.toFixed(2)}%`,
  },
]

export default function BolsaWidget() {
  const [acciones, setAcciones] = useState(ACCIONES_DEFAULT)
  const [datos, setDatos] = useState({})
  const [cargando, setCargando] = useState(true)
  const [error, setError] = useState(null)
  const [seleccionada, setSeleccionada] = useState(null)
  const [busqueda, setBusqueda] = useState('')
  const [trm, setTrm] = useState(TRM_DEFAULT)

  // ─────────────────────────────────────────────────────────
  // TRM
  // ─────────────────────────────────────────────────────────
  useEffect(() => {
    fetch('https://david-ekcn.onrender.com/api/bolsa/trm/usd-cop')
      .then((r) => (r.ok ? r.json() : null))
      .then((data) => {
        if (data?.trm) {
          setTrm(data.trm)
        }
      })
      .catch(() => {})
  }, [])

  // ─────────────────────────────────────────────────────────
  // Fetch acciones
  // ─────────────────────────────────────────────────────────
  const fetchAcciones = async (lista) => {
    try {
      setError(null)

      const nuevos = {}

      await Promise.all(
        lista.map(async (accion) => {
          const res = await fetch(
            `https://david-ekcn.onrender.com/api/bolsa/${accion.symbol}`
            
          )

          const data = await res.json()

          if (!res.ok || data.ok === false) return

          nuevos[accion.symbol] = {
            precio: data.c ?? 0,
            cambio: data.d ?? 0,
            porcentaje: data.dp ?? 0,
            maximo: data.h ?? 0,
            minimo: data.l ?? 0,
            apertura: data.o ?? 0,
            cierreAnt: data.pc ?? 0,
            subio: (data.d ?? 0) >= 0,
          }
        })
      )

      setDatos((prev) => ({
        ...prev,
        ...nuevos,
      }))
    } catch (_) {
      setError('No se pudo conectar con la API de bolsa')
    }
  }

  // ─────────────────────────────────────────────────────────
  // Auto actualización
  // ─────────────────────────────────────────────────────────
  useEffect(() => {
    setCargando(true)

    fetchAcciones(acciones).finally(() => {
      setCargando(false)
    })

    const intervalo = setInterval(() => {
      fetchAcciones(acciones)
    }, 5 * 60 * 1000)

    return () => clearInterval(intervalo)
  }, [acciones])

  // ─────────────────────────────────────────────────────────
  // Agregar acción
  // ─────────────────────────────────────────────────────────
  const agregarAccion = async () => {
    const sym = busqueda.trim().toUpperCase()

    if (!sym) return

    if (acciones.find((a) => a.symbol === sym)) {
      setError('Ese símbolo ya está agregado')
      return
    }

    const nueva = {
      symbol: sym,
      nombre: sym,
      icono: '📈',
      pais: 'Internacional',
    }

    setAcciones((prev) => [...prev, nueva])
    setBusqueda('')

    try {
      const res = await fetch(
        `https://david-ekcn.onrender.com/api/bolsa/${sym}`
      )

      const data = await res.json()

      if (!res.ok || data.ok === false) {
        setError(data.mensaje || 'No se pudo consultar el símbolo')
        return
      }

      setDatos((prev) => ({
        ...prev,
        [sym]: {
          precio: data.c ?? 0,
          cambio: data.d ?? 0,
          porcentaje: data.dp ?? 0,
          maximo: data.h ?? 0,
          minimo: data.l ?? 0,
          apertura: data.o ?? 0,
          cierreAnt: data.pc ?? 0,
          subio: (data.d ?? 0) >= 0,
        },
      }))
    } catch (_) {
      setError('No se pudo conectar con la API')
    }
  }

  // ─────────────────────────────────────────────────────────
  // Eliminar acción
  // ─────────────────────────────────────────────────────────
  const eliminarAccion = (symbol) => {
    setAcciones((prev) =>
      prev.filter((a) => a.symbol !== symbol)
    )

    setDatos((prev) => {
      const copia = { ...prev }
      delete copia[symbol]
      return copia
    })

    if (seleccionada?.symbol === symbol) {
      setSeleccionada(null)
    }
  }

  // ─────────────────────────────────────────────────────────
  // Seleccionar acción
  // ─────────────────────────────────────────────────────────
  const seleccionarAccion = (accion) => {
    setSeleccionada(
      seleccionada?.symbol === accion.symbol
        ? null
        : {
            ...accion,
            ...datos[accion.symbol],
          }
    )
  }

  // ─────────────────────────────────────────────────────────
  // Formato COP
  // ─────────────────────────────────────────────────────────
  const formatCOP = (usd) => {
    return (usd * trm).toLocaleString('es-CO', {
      style: 'currency',
      currency: 'COP',
      maximumFractionDigits: 0,
    })
  }

  const accionesConDatos = acciones.filter(
    (accion) => datos[accion.symbol]
  )

  return (
    <section className="w-full rounded-2xl border border-white/10 bg-slate-950/40 p-6 shadow-[0_18px_45px_rgba(0,0,0,0.25)] backdrop-blur-xl">

      {/* HEADER */}
      <div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">

        <div className="flex items-center gap-4">
          <div className="grid h-12 w-12 place-items-center rounded-xl bg-cyan-400/10 border border-cyan-300/20 text-cyan-100 font-black">
            BV
          </div>

          <div>
            <h2 className="text-xl font-black text-white">
              Bolsa de Valores
            </h2>

            <p className="text-sm text-slate-400">
              Seguimiento financiero en tiempo real
            </p>
          </div>
        </div>

        <div className="flex flex-wrap items-center gap-2">

          <span className="rounded-lg border border-emerald-300/20 bg-emerald-300/10 px-3 py-1.5 text-xs font-bold text-emerald-100">
            TRM {trm.toLocaleString('es-CO')} COP
          </span>

          <span className="rounded-lg border border-amber-300/20 bg-amber-300/10 px-3 py-1.5 text-xs font-bold text-amber-100">
            Finnhub API
          </span>

        </div>
      </div>

      {/* BUSCADOR */}
      <div className="mt-6 flex flex-col gap-3 sm:flex-row">

        <input
          type="text"
          value={busqueda}
          onChange={(e) => setBusqueda(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter') agregarAccion()
          }}
          placeholder="Agregar símbolo (AAPL, TSLA, NVDA...)"
          className="min-h-11 flex-1 rounded-xl border border-white/10 bg-white/5 px-4 text-sm text-white outline-none transition placeholder:text-slate-500 focus:border-cyan-300/50 focus:ring-2 focus:ring-cyan-300/10"
        />

        <button
          type="button"
          onClick={agregarAccion}
          disabled={!busqueda.trim()}
          className="min-h-11 rounded-xl bg-cyan-400 px-5 text-sm font-black text-slate-950 transition hover:bg-cyan-300 disabled:cursor-not-allowed disabled:bg-slate-700 disabled:text-slate-400"
        >
          Agregar
        </button>

      </div>

      {/* MENSAJES */}
      <div className="mt-4 min-h-6">

        {cargando && (
          <p className="text-sm text-slate-400">
            Consultando precios...
          </p>
        )}

        {error && (
          <p className="rounded-lg border border-rose-300/20 bg-rose-300/10 px-3 py-2 text-sm text-rose-100">
            {error}
          </p>
        )}

      </div>

      {/* GRID */}
      <div className="mt-5 grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-5">

        {accionesConDatos.map((accion) => {
          const d = datos[accion.symbol]

          const activa =
            seleccionada?.symbol === accion.symbol

          return (
            <article
              key={accion.symbol}
              onClick={() => seleccionarAccion(accion)}
              className={`group relative cursor-pointer rounded-2xl border p-4 transition-all duration-300 hover:-translate-y-1 ${
                activa
                  ? 'border-cyan-300/60 bg-cyan-300/10'
                  : 'border-white/10 bg-white/5 hover:bg-white/10'
              }`}
            >

              {/* ELIMINAR */}
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation()
                  eliminarAccion(accion.symbol)
                }}
                className="absolute right-3 top-3 grid h-7 w-7 place-items-center rounded-lg border border-white/10 text-xs text-slate-400 opacity-70 transition hover:border-rose-300/40 hover:bg-rose-400/10 hover:text-rose-100 group-hover:opacity-100"
              >
                ✕
              </button>

              {/* TOP */}
              <div className="flex items-start gap-3 pr-8">

                <div className="text-3xl">
                  {accion.icono}
                </div>

                <div className="min-w-0">
                  <h3 className="truncate text-sm font-black text-white">
                    {accion.nombre}
                  </h3>

                  <p className="mt-0.5 text-xs text-slate-400">
                    {accion.symbol} · {accion.pais}
                  </p>
                </div>

              </div>

              {/* PRECIO */}
              <div className="mt-5">

                <p className="text-2xl font-black text-white">
                  ${d.precio.toFixed(2)}

                  <span className="ml-1 text-[0.65rem] text-slate-400">
                    USD
                  </span>
                </p>

                <p className="mt-1 text-xs text-slate-400">
                  {formatCOP(d.precio)}
                </p>

              </div>

              {/* VARIACIÓN */}
              <div
                className={`mt-4 inline-flex rounded-lg px-2.5 py-1 text-xs font-black ${
                  d.subio
                    ? 'bg-emerald-400/10 text-emerald-200'
                    : 'bg-rose-400/10 text-rose-200'
                }`}
              >
                {d.subio ? '▲' : '▼'}{' '}
                {d.subio ? '+' : ''}
                {d.cambio.toFixed(2)} (
                {d.porcentaje.toFixed(2)}%)
              </div>

            </article>
          )
        })}
      </div>

      {/* DETALLE */}
      {seleccionada && (
        <section className="mt-6 rounded-2xl border border-white/10 bg-white/5 p-5">

          <div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between">

            <div>
              <p className="text-xs font-bold uppercase tracking-wider text-cyan-200">
                Detalle de acción
              </p>

              <h3 className="mt-1 text-2xl font-black text-white">
                {seleccionada.icono} {seleccionada.nombre}
              </h3>

              <p className="text-sm text-slate-400">
                {seleccionada.symbol} · {seleccionada.pais}
              </p>
            </div>

            <div
              className={`rounded-xl px-4 py-2 ${
                seleccionada.subio
                  ? 'bg-emerald-400/10 text-emerald-100'
                  : 'bg-rose-400/10 text-rose-100'
              }`}
            >
              <p className="text-xs font-bold uppercase">
                Variación
              </p>

              <p className="text-lg font-black">
                {seleccionada.subio ? '+' : ''}
                {seleccionada.porcentaje.toFixed(2)}%
              </p>
            </div>

          </div>

          {/* MÉTRICAS */}
          <div className="mt-5 grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-3">

            {metricasDetalle(
              seleccionada,
              formatCOP
            ).map((item) => (
              <div
                key={item.label}
                className="rounded-xl border border-white/10 bg-slate-950/35 p-4"
              >

                <p className="text-xs font-bold uppercase tracking-wider text-slate-500">
                  {item.label}
                </p>

                <p className="mt-2 text-lg font-black text-white">
                  {item.valor}
                </p>

                <p className="mt-1 text-xs text-slate-400">
                  {item.apoyo}
                </p>

              </div>
            ))}

          </div>

        </section>
      )}

      {/* FOOTER */}
      <div className="mt-5 flex flex-col gap-1 text-xs text-slate-500 sm:flex-row sm:items-center sm:justify-between">

        <span>
          Actualización automática cada 5 minutos
        </span>

        <span>
          Haz clic en una acción para ver detalles
        </span>

      </div>

    </section>
  )
}

import { useState, useEffect, useRef } from 'react'
import { useNavigate, useLocation } from 'react-router-dom'
import { useNotificaciones } from '../context/NotificacionesContext'
import { useAuth } from '../context/AuthContext'

const navItems = [
  { href: '/Dashboard', emoji: '📊', label: 'Dashboard' },
  { href: '/ModulosIngresos', emoji: '💰', label: 'Ingresos' },
  { href: '/ModulosGastos', emoji: '💸', label: 'Gastos' },
  { href: '/ModuloAhorros', emoji: '🎯', label: 'Ahorrar' },
  { href: '/ModuloImprevistos', emoji: '🛡️', label: 'Imprevistos' },
  { href: '/ModuloFondoEmergencia', emoji: '🆘', label: 'Fondo Emergencia' },
  { href: '/ModuloDeudas', emoji: '💳', label: 'Deudas' },
  { href: '/ModulosDependientes', emoji: '👩‍👧‍👦', label: 'Dependientes' },
  { href: '/ModulosCategorias', emoji: '🧩', label: 'Categorias' },
  { href: '/ModulosPresupuestos', emoji: '📋', label: 'Presupuestos' },
  { href: '/Noticias', emoji: '📰', label: 'Noticias' },
  { href: '/Reportes', emoji: '📈', label: 'Reportes' },
  // { href: '/exportar', emoji: '📤', label: 'Exportar' },
]

export default function HeaderModulos({ section = 'Dashboard' }) {
  const navigate = useNavigate()
  const { logout } = useAuth()
  const location = useLocation()
  const [menuOpen, setMenuOpen] = useState(false)
  const { noLeidasCount, notificacionPendiente, limpiarNotificacionPendiente } = useNotificaciones()
  const [mensajeVisible, setMensajeVisible] = useState(null)
  const [pulsando, setPulsando] = useState(false)
  const timeoutRef = useRef(null)


  useEffect(() => {
    if (!notificacionPendiente) return

    setMensajeVisible(notificacionPendiente.mensaje)
    setPulsando(true)

    if (timeoutRef.current) clearTimeout(timeoutRef.current)
    timeoutRef.current = setTimeout(() => {
      setMensajeVisible(null)
      setPulsando(false)
      limpiarNotificacionPendiente()
    }, 3000)

    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current)
    }
  }, [notificacionPendiente, limpiarNotificacionPendiente])

  const navButtonClass = isActive =>
    isActive
      ? 'w-full md:w-auto flex items-center gap-1.5 px-4 py-3 md:px-2.5 md:py-1.5 lg:px-3 lg:py-2 rounded-xl md:rounded-[10px] text-left font-bold text-amber-300 bg-amber-400/20 border border-amber-400/50 shadow-[0_0_12px_rgba(251,191,36,0.4)] transition-all whitespace-nowrap'
      : 'w-full md:w-auto flex items-center gap-1.5 px-4 py-3 md:px-2.5 md:py-1.5 lg:px-3 lg:py-2 rounded-xl md:rounded-[10px] text-left font-semibold text-white bg-white/10 border border-white/5 hover:-translate-y-px hover:shadow-[0_1px_8px_rgba(255,187,0,0.4)] transition-all whitespace-nowrap'

  const handleLogout = () => { 
    logout();
    window.location.replace('/Login');
  }
  return (
    <header className="relative z-10 w-full flex flex-col items-center pt-4 sm:pt-5">
      <section className="w-full max-w-[1400px] flex flex-col gap-4 px-4 sm:px-6 md:px-10 mb-4 sm:mb-6">
        <div className="w-full grid grid-cols-2 sm:grid-cols-3 items-center gap-3">
          <button
            onClick={() => navigate('/IndexLogeado')}
            className="justify-self-start flex items-center gap-2 px-3 py-2 text-xs sm:text-sm font-bold rounded-xl sm:rounded-2xl border border-white/10 bg-transparent text-white transition-all duration-300 hover:bg-green-600 hover:border-green-500/50 hover:-translate-y-px hover:shadow-[0_4px_10px_rgba(31,187,31,0.4)]"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M3 9.75L12 3l9 6.75V21a.75.75 0 01-.75.75H15.75a.75.75 0 01-.75-.75v-5.25H9V21a.75.75 0 01-.75.75H3.75A.75.75 0 013 21V9.75z" /></svg>
            Inicio
          </button>

          <div className="col-span-2 row-start-1 sm:col-span-1 sm:col-start-2 flex flex-col items-center gap-0.5 pointer-events-none">
            <h1 className="text-2xl sm:text-3xl md:text-4xl font-black tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-amber-300 via-amber-400 to-orange-500">
              AhorrApp
            </h1>
            <span className="text-[0.6rem] sm:text-[0.65rem] text-zinc-500 font-semibold tracking-widest uppercase">
              {section}
            </span>
          </div>

          <div className="justify-self-end flex items-center gap-2">
            <div className="relative">
              <button
                onClick={() => navigate('/Configuracion?tab=notificaciones')}
                aria-label="Notificaciones"
                className={`relative flex items-center justify-center w-9 h-9 sm:w-10 sm:h-10 rounded-xl sm:rounded-2xl border bg-transparent text-white transition-all duration-300 hover:bg-amber-500/20 hover:border-amber-400/50 hover:-translate-y-px ${pulsando ? 'animate-[campana-pulso_0.6s_ease-in-out_2]' : 'border-white/10'}`}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="w-4 h-4 sm:w-5 sm:h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M14.857 17.082a23.848 23.848 0 005.454-1.31A8.967 8.967 0 0118 9.75v-.7V9A6 6 0 006 9v.75a8.967 8.967 0 01-2.312 6.022c1.733.64 3.56 1.085 5.455 1.31m5.714 0a24.255 24.255 0 01-5.714 0m5.714 0a3 3 0 11-5.714 0" /></svg>
                {noLeidasCount > 0 && (
                  <span className="absolute -top-1 -right-1 flex items-center justify-center min-w-[18px] h-[18px] px-1 rounded-full bg-red-500 text-white text-[0.65rem] font-bold leading-none">
                    {noLeidasCount > 99 ? '99+' : noLeidasCount}
                  </span>
                )}
              </button>

              {mensajeVisible && (
                <div className="absolute right-0 top-full mt-2 w-60 sm:w-72 px-3.5 py-2.5 rounded-xl border border-amber-400/30 bg-slate-950/95 backdrop-blur-lg shadow-[0_8px_24px_rgba(0,0,0,0.45)] text-xs sm:text-sm text-white z-20 animate-[anclado-in_0.2s_ease-out]">
                  {mensajeVisible}
                </div>
              )}
            </div>

            <button
              onClick={handleLogout}
              className="flex items-center gap-2 px-3 py-2 text-xs sm:text-sm font-bold rounded-xl sm:rounded-2xl border border-white/10 bg-transparent text-white transition-all duration-300 hover:bg-red-600 hover:border-red-500/40 hover:-translate-y-px hover:shadow-[0_4px_10px_rgba(228,33,33,0.4)]"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
              
              <span className="hidden sm:inline">Cerrar Sesión</span>
              <span className="sm:hidden">Salir</span>
            </button>
          </div>
        </div>
      </section>

      <style>{`
        @keyframes campana-pulso {
          0%, 100% { border-color: rgba(255,255,255,0.1); box-shadow: none; }
          50% { border-color: rgba(251,191,36,0.7); box-shadow: 0 0 10px rgba(251,191,36,0.5); }
        }
        @keyframes anclado-in {
          from { opacity: 0; transform: translateY(-6px); }
          to   { opacity: 1; transform: translateY(0); }
        }
      `}</style>

      <nav className="w-full px-4 sm:px-6 md:px-10">
        <div className="md:hidden">
          <button
            type="button"
            onClick={() => setMenuOpen(!menuOpen)}
            className="flex w-full items-center justify-between rounded-xl border border-white/10 bg-white/10 px-4 py-3 font-bold text-white shadow-[0_2px_8px_rgba(255,255,255,0.1)]"
          >
            <span>Menú</span>
            <span>{menuOpen ? '▲' : '▼'}</span>
          </button>

          {menuOpen && (
            <ul className="mt-3 grid grid-cols-1 gap-2 rounded-2xl border border-white/10 bg-slate-950/85 p-3 backdrop-blur-lg">
              {navItems.map(item => {
                const isActive = location.pathname === item.href

                return (
                  <li key={item.href}>
                    <button
                      type="button"
                      onClick={() => {
                        navigate(item.href)
                        setMenuOpen(false)
                      }}
                      className={navButtonClass(isActive)}
                    >
                      <span>{item.emoji}</span>
                      <span>{item.label}</span>
                    </button>
                  </li>
                )
              })}
            </ul>
          )}
        </div>

        <ul className="hidden flex-wrap items-center justify-center gap-x-2 gap-y-2 pb-2 text-sm md:flex lg:gap-x-3 lg:gap-y-3 lg:text-base">
          {navItems.map(item => {
            const isActive = location.pathname === item.href

            return (
              <li key={item.href}>
                <button
                  type="button"
                  onClick={() => navigate(item.href)}
                  className={navButtonClass(isActive)}
                >
                  <span>{item.emoji}</span>
                  <span>{item.label}</span>
                </button>
              </li>
            )
          })}
        </ul>
      </nav>
    </header>
  )
}

import { useState, useEffect, useCallback } from 'react'
import {
  getNotificaciones,
  marcarNotificacionLeida,
  marcarTodasNotificacionesLeidas,
  archivarNotificacion,
  eliminarNotificacion,
} from '../services/api'
import { useToast } from '../context/ToastContext'
import { useNotificaciones } from '../context/NotificacionesContext'

const ICONO_POR_TIPO = {
  sistema: '⚙️',
  recordatorio: '⏰',
  sugerencia: '💡',
  alerta_presupuesto: '⚠️',
}

const FILTROS = [
  { id: 'todas', label: 'Todas' },
  { id: 'no_leidas', label: 'No leídas' },
  { id: 'archivadas', label: 'Archivadas' },
]

const formatearFecha = (isoString) => {
  const fecha = new Date(isoString)
  return fecha.toLocaleDateString('es-CO', {
    day: 'numeric',
    month: 'short',
    hour: '2-digit',
    minute: '2-digit',
  })
}

export default function Historialnotificaciones() {
  const { mostrarToast } = useToast()
  const { refrescarCount } = useNotificaciones()

  const [filtro, setFiltro] = useState('todas')
  const [pagina, setPagina] = useState(1)
  const [notificaciones, setNotificaciones] = useState([])
  const [paginacion, setPaginacion] = useState(null)
  const [cargando, setCargando] = useState(true)
  const [error, setError] = useState(null)

  const cargar = useCallback(async () => {
    setCargando(true)
    setError(null)
    try {
      const params = { page: String(pagina), limit: '10' }
      if (filtro === 'no_leidas') params.leida = 'false'
      if (filtro === 'archivadas') params.archivada = 'true'

      const { notificaciones: data, paginacion: pag } = await getNotificaciones(params)
      setNotificaciones(data)
      setPaginacion(pag)
    } catch (err) {
      setError('No se pudo cargar el historial de notificaciones.')
    } finally {
      setCargando(false)
    }
  }, [filtro, pagina])

  useEffect(() => {
    cargar()
  }, [cargar])

  const cambiarFiltro = (nuevoFiltro) => {
    setFiltro(nuevoFiltro)
    setPagina(1)
  }

  const handleLeer = async (id) => {
    try {
      await marcarNotificacionLeida(id)
      setNotificaciones(prev => prev.map(n => (n.id === id ? { ...n, leida: true } : n)))
      refrescarCount()
    } catch (err) {
      mostrarToast('No se pudo marcar como leída', 'error')
    }
  }

  const handleLeerTodas = async () => {
    try {
      await marcarTodasNotificacionesLeidas()
      setNotificaciones(prev => prev.map(n => ({ ...n, leida: true })))
      refrescarCount()
      mostrarToast('Todas las notificaciones marcadas como leídas')
    } catch (err) {
      mostrarToast('No se pudieron marcar todas como leídas', 'error')
    }
  }

  const handleArchivar = async (id) => {
    try {
      await archivarNotificacion(id)
      setNotificaciones(prev => prev.filter(n => n.id !== id))
      mostrarToast('Notificación archivada')
      refrescarCount()
    } catch (err) {
      mostrarToast('No se pudo archivar la notificación', 'error')
    }
  }

  const handleEliminar = async (id) => {
    if (!window.confirm('¿Eliminar esta notificación de forma permanente?')) return
    try {
      await eliminarNotificacion(id)
      setNotificaciones(prev => prev.filter(n => n.id !== id))
      mostrarToast('Notificación eliminada')
      refrescarCount()
    } catch (err) {
      mostrarToast('No se pudo eliminar la notificación', 'error')
    }
  }

  return (
    <div className="flex flex-col gap-5">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h3 className="text-base font-extrabold text-[#fbbf24]">📋 Historial de notificaciones</h3>
          <p className="text-xs text-[#a1a1aa] mt-1">
            Aquí encuentras todos los avisos relacionados con tu actividad financiera.
          </p>
        </div>

        <button
          onClick={handleLeerTodas}
          className="px-3.5 py-2 rounded-xl text-xs font-bold border border-white/15 bg-white/[0.06] text-[#a1a1aa] hover:bg-white/[0.1] hover:text-white transition-colors duration-150"
        >
          Marcar todas como leídas
        </button>
      </div>

      <div className="flex gap-2">
        {FILTROS.map(f => (
          <button
            key={f.id}
            onClick={() => cambiarFiltro(f.id)}
            className={`px-3.5 py-1.5 rounded-full text-xs font-bold border transition-colors duration-150 ${
              filtro === f.id
                ? 'text-amber-300 bg-amber-400/20 border-amber-400/50'
                : 'text-[#a1a1aa] bg-white/[0.05] border-white/10 hover:bg-white/[0.09]'
            }`}
          >
            {f.label}
          </button>
        ))}
      </div>

      {cargando ? (
        <p className="text-zinc-500 text-sm italic">Cargando notificaciones...</p>
      ) : error ? (
        <p className="text-red-400 text-sm">{error}</p>
      ) : notificaciones.length === 0 ? (
        <p className="text-zinc-500 italic text-sm">
          {filtro === 'no_leidas'
            ? 'No tienes notificaciones sin leer.'
            : filtro === 'archivadas'
            ? 'No tienes notificaciones archivadas.'
            : 'Aún no tienes notificaciones. Aparecerán aquí conforme uses la app.'}
        </p>
      ) : (
        <div className="flex flex-col gap-2.5">
          {notificaciones.map(n => (
            <div
              key={n.id}
              className={`flex items-start gap-3 rounded-2xl border p-4 transition-colors duration-150 ${
                n.leida
                  ? 'border-white/[0.07] bg-white/[0.02]'
                  : 'border-amber-400/20 bg-amber-400/[0.06]'
              }`}
            >
              <span className="text-lg leading-none mt-0.5">
                {ICONO_POR_TIPO[n.tipo] ?? '🔔'}
              </span>

              <div className="flex-1 min-w-0">
                <p className={`text-sm ${n.leida ? 'text-[#d4d4d8]' : 'text-white font-semibold'}`}>
                  {n.mensaje}
                </p>
                <p className="text-[0.7rem] text-zinc-500 mt-1">{formatearFecha(n.fecha)}</p>
              </div>

              <div className="flex gap-1.5 shrink-0">
                {!n.leida && !n.archivada && (
                  <button
                    onClick={() => handleLeer(n.id)}
                    title="Marcar como leída"
                    className="w-7 h-7 flex items-center justify-center rounded-lg text-xs border border-emerald-400/40 bg-emerald-400/10 text-emerald-300 hover:bg-emerald-400/20 transition-colors duration-150"
                  >
                    ✓
                  </button>
                )}
                {!n.archivada && (
                  <button
                    onClick={() => handleArchivar(n.id)}
                    title="Archivar"
                    className="w-7 h-7 flex items-center justify-center rounded-lg text-xs border border-indigo-400/40 bg-indigo-400/10 text-[#818cf8] hover:bg-indigo-400/20 transition-colors duration-150"
                  >
                    🗂
                  </button>
                )}
                <button
                  onClick={() => handleEliminar(n.id)}
                  title="Eliminar"
                  className="w-7 h-7 flex items-center justify-center rounded-lg text-xs border border-red-400/40 bg-red-400/10 text-[#f87171] hover:bg-red-400/20 transition-colors duration-150"
                >
                  ✕
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {paginacion && paginacion.totalPaginas > 1 && (
        <div className="flex items-center justify-center gap-2 pt-2">
          <button
            onClick={() => setPagina(p => Math.max(1, p - 1))}
            disabled={pagina <= 1}
            className="px-3 py-1.5 rounded-lg text-xs font-bold border border-white/10 bg-white/[0.05] text-[#a1a1aa] disabled:opacity-40 disabled:cursor-not-allowed hover:bg-white/[0.09] transition-colors duration-150"
          >
            ← Anterior
          </button>
          <span className="text-xs text-[#a1a1aa]">
            Página {paginacion.page} de {paginacion.totalPaginas}
          </span>
          <button
            onClick={() => setPagina(p => Math.min(paginacion.totalPaginas, p + 1))}
            disabled={pagina >= paginacion.totalPaginas}
            className="px-3 py-1.5 rounded-lg text-xs font-bold border border-white/10 bg-white/[0.05] text-[#a1a1aa] disabled:opacity-40 disabled:cursor-not-allowed hover:bg-white/[0.09] transition-colors duration-150"
          >
            Siguiente →
          </button>
        </div>
      )}
    </div>
  )
}

import { useState, useEffect } from 'react'
import { getPreferenciasNotificacion, actualizarPreferenciasNotificacion } from '../services/api'
import { useToast } from '../context/ToastContext'

const INFO_TIPOS = {
  sistema: {
    label: 'Mensajes del sistema',
