// src/context/NotificacionesContext.jsx
import { createContext, useState, useContext, useEffect, useCallback, useRef } from 'react';
import { useAuth } from '../context/AuthContext';
import { getNoLeidasCount, getNotificaciones } from '../services/api';

const NotificacionesContext = createContext();

const INTERVALO_POLLING_MS = 60000; // 60 segundos (respaldo, ej. recordatorios del cron)
const LIMITE_REVISION = 5; // cuantas no leidas recientes se revisan por ciclo

export const NotificacionesProvider = ({ children }) => {
  const { isAuthenticated, loading } = useAuth();
  const [noLeidasCount, setNoLeidasCount] = useState(0);
  // Notificación pendiente de mostrar como toast anclado a la campana.
  // null = no hay nada pendiente. HeaderModulos la consume y la limpia.
  const [notificacionPendiente, setNotificacionPendiente] = useState(null);
  const intervaloRef = useRef(null);
  const ultimoIdVistoRef = useRef(null); // null = aun no se ha sincronizado

  const refrescarCount = useCallback(async () => {
    const count = await getNoLeidasCount();
    setNoLeidasCount(count);
  }, []);

  const revisarNotificacionesNuevas = useCallback(async () => {
    try {
      const { notificaciones } = await getNotificaciones({ leida: 'false', limit: String(LIMITE_REVISION) });
      if (notificaciones.length === 0) return;

      const idsOrdenadosAsc = [...notificaciones].sort((a, b) => a.id - b.id);
      const esPrimeraSincronizacion = ultimoIdVistoRef.current === null;

      if (!esPrimeraSincronizacion) {
        const nuevas = idsOrdenadosAsc.filter((n) => n.id > ultimoIdVistoRef.current);
        if (nuevas.length > 0) {
          // Solo se muestra una a la vez; si llegaron varias de golpe,
          // se prioriza la más reciente (última del arreglo ordenado asc).
          setNotificacionPendiente(nuevas[nuevas.length - 1]);
        }
      }

      const idMaximo = idsOrdenadosAsc[idsOrdenadosAsc.length - 1].id;
      ultimoIdVistoRef.current = Math.max(ultimoIdVistoRef.current ?? 0, idMaximo);
    } catch (error) {
      console.error('Error en revisarNotificacionesNuevas:', error);
    }
  }, []);

  const ejecutarCiclo = useCallback(async () => {
    await refrescarCount();
    await revisarNotificacionesNuevas();
  }, [refrescarCount, revisarNotificacionesNuevas]);


  const revisarAhora = useCallback(() => {
    ejecutarCiclo();
  }, [ejecutarCiclo]);

  const limpiarNotificacionPendiente = useCallback(() => {
    setNotificacionPendiente(null);
  }, []);

  useEffect(() => {

    if (loading || !isAuthenticated) {
      setNoLeidasCount(0);
      ultimoIdVistoRef.current = null; 
      return;
    }


    ejecutarCiclo();

    intervaloRef.current = setInterval(ejecutarCiclo, INTERVALO_POLLING_MS);

    return () => {
      if (intervaloRef.current) clearInterval(intervaloRef.current);
    };
  }, [isAuthenticated, loading, ejecutarCiclo]);

  const value = {
    noLeidasCount,
    refrescarCount,
    revisarAhora,
    notificacionPendiente,
    limpiarNotificacionPendiente,
  };

  return (
    <NotificacionesContext.Provider value={value}>
      {children}
    </NotificacionesContext.Provider>
  );
};

export const useNotificaciones = () => {
  const context = useContext(NotificacionesContext);
  if (!context) {
    throw new Error('useNotificaciones debe usarse dentro de NotificacionesProvider');
  }
  return context;
};

// src/context/ToastContext.jsx
import { createContext, useState, useContext, useCallback, useRef } from 'react'

const ToastContext = createContext()

const DURACION_MS = 3000

// Estilos por tipo de toast. 'success' es el caso por defecto
// (acorde al acento ámbar/dorado ya usado en HeaderModulos).
const ESTILOS_POR_TIPO = {
  success: {
    borde: 'border-amber-400/40',
    icono: '✓',
    iconoFondo: 'bg-amber-400/20 text-amber-300',
  },
  error: {
    borde: 'border-red-500/40',
    icono: '✕',
    iconoFondo: 'bg-red-500/20 text-red-400',
  },
  info: {
    borde: 'border-sky-400/40',
    icono: 'ℹ',
    iconoFondo: 'bg-sky-400/20 text-sky-300',
  },
}

export const ToastProvider = ({ children }) => {
  const [toasts, setToasts] = useState([])
  const idCounterRef = useRef(0)

  const mostrarToast = useCallback((mensaje, tipo = 'success') => {
    idCounterRef.current += 1
    const id = idCounterRef.current

    setToasts((prev) => [...prev, { id, mensaje, tipo }])

    setTimeout(() => {
      setToasts((prev) => prev.filter((t) => t.id !== id))
    }, DURACION_MS)
  }, [])

  const cerrarToast = useCallback((id) => {
    setToasts((prev) => prev.filter((t) => t.id !== id))
  }, [])

  return (
    <ToastContext.Provider value={{ mostrarToast }}>
      {children}

      {/* Banner centrado arriba, debajo del header */}
      <div className="fixed top-4 left-1/2 -translate-x-1/2 z-[100] flex flex-col items-center gap-2 w-[calc(100%-2rem)] max-w-md pointer-events-none">
        {toasts.map(({ id, mensaje, tipo }) => {
          const estilo = ESTILOS_POR_TIPO[tipo] ?? ESTILOS_POR_TIPO.success

          return (
            <div
              key={id}
              role="status"
              className={`pointer-events-auto w-full flex items-center gap-3 px-4 py-3 rounded-xl sm:rounded-2xl border ${estilo.borde} bg-slate-950/90 backdrop-blur-lg shadow-[0_8px_24px_rgba(0,0,0,0.4)] animate-[toast-in_0.25s_ease-out]`}
            >
              <span className={`flex items-center justify-center w-6 h-6 rounded-full text-xs font-bold shrink-0 ${estilo.iconoFondo}`}>
                {estilo.icono}
              </span>
              <span className="flex-1 text-sm font-medium text-white">
                {mensaje}
              </span>
              <button
                onClick={() => cerrarToast(id)}
                aria-label="Cerrar"
                className="pointer-events-auto text-white/40 hover:text-white/80 transition-colors text-sm font-bold leading-none px-1"
              >
                ✕
              </button>
            </div>
          )
        })}
      </div>

      <style>{`
        @keyframes toast-in {
          from { opacity: 0; transform: translateY(-12px); }
          to   { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </ToastContext.Provider>
  )
}

export const useToast = () => {
  const context = useContext(ToastContext)
  if (!context) {
    throw new Error('useToast debe usarse dentro de ToastProvider')
  }
  return context
}

import { useState, useEffect } from 'react'
import { useSearchParams, Link } from 'react-router-dom'
import HeaderModulos from '../components/HeaderModulos'
import Historialnotificaciones from '../components/Historialnotificaciones'
import Preferenciasnotificaciones from '../components/Preferenciasnotificaciones'
import MisMovimientos from '../components/Mismovimientos'
import MiCuenta from '../components/Micuenta'
import { useAuth } from '../context/AuthContext'

const SECCIONES = [
  { id: 'notificaciones', label: 'Notificaciones', emoji: '🔔' },
  { id: 'preferencias', label: 'Preferencias', emoji: '🎛️' },
  { id: 'movimientos', label: 'Mis movimientos', emoji: '📊' },
  { id: 'cuenta', label: 'Mi cuenta', emoji: '👤' },
]

export default function Configuracion() {
  const { hasRole } = useAuth()
  const puedeVerPanelAdmin = hasRole('admin') || hasRole('superuser')
  const [searchParams] = useSearchParams()
  const tabInicial = searchParams.get('tab')
  const [seccionActiva, setSeccionActiva] = useState(
    SECCIONES.some(s => s.id === tabInicial) ? tabInicial : 'notificaciones'
  )

