        <p key={p.name} style={{ color: p.color }} className="mb-0.5">
          {p.name}: <span className="text-white font-semibold">${Number(p.value).toLocaleString('es-CO')}</span>
        </p>
      ))}
    </div>
  )
}

// ── Tooltip personalizado para la gráfica de área ────────────
