                          </td>
                          <td className="px-4 py-3 text-sm text-zinc-300">{fmtFecha(a.fecha_meta)}</td>
                          <td className="px-4 py-3 text-sm font-extrabold text-amber-400">{fmt(a.monto)}</td>
