            <label className={labelCls}>Total de cuotas</label>
            <input className={inputCls} type="number" name="cuotas_total" min="1" step="1" placeholder="Vacío si es pago único" value={modalEditar.cuotas_total} onChange={handleChange} />

            <label className={labelCls}>Fecha de inicio</label>
            <input className={inputCls} type="date" name="fecha_inicio" value={modalEditar.fecha_inicio} onChange={handleChange} />

            <label className={labelCls}>Fecha de fin</label>
            <input className={inputCls} type="date" name="fecha_fin" value={modalEditar.fecha_fin} onChange={handleChange} />

            {errorModal && <p className="mt-3 p-[10px_14px] rounded-[10px] bg-red-400/[0.12] border border-red-400/35 text-red-400 text-[0.8rem] font-semibold">{errorModal}</p>}
            <div className="mt-6 flex justify-end gap-2.5">
              <button onClick={() => setModalEditar(null)} className="px-5 py-2.5 rounded-[10px] text-sm font-bold bg-transparent text-zinc-400 border border-white/[0.15] hover:bg-white/[0.07] transition-colors">Cancelar</button>
              <button onClick={guardar} disabled={guardando} className="px-5 py-2.5 rounded-[10px] text-sm font-bold text-white disabled:opacity-50 disabled:cursor-not-allowed transition-opacity"
                style={{ background: guardando ? 'rgba(192,132,252,0.4)' : 'linear-gradient(135deg, #c084fc, #a855f7)' }}>
                {guardando ? 'Guardando...' : 'Guardar cambios'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Modal Eliminar */}
      {confirmarId && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-4 bg-black/65 backdrop-blur-md">
          <div className="w-full max-w-[380px] rounded-[20px] p-7 border border-red-400/25 shadow-[0_24px_60px_rgba(0,0,0,0.6)]"
            style={{ background: 'rgba(15,23,42,0.95)' }}>
            <h4 className="text-lg font-extrabold text-red-400 mb-2">🗑️ ¿Eliminar deuda?</h4>
            <p className="text-sm text-zinc-400">Esta acción no se puede deshacer.</p>
            <div className="mt-6 flex justify-end gap-2.5">
              <button onClick={() => setConfirmarId(null)} className="px-5 py-2.5 rounded-[10px] text-sm font-bold bg-transparent text-zinc-400 border border-white/[0.15] hover:bg-white/[0.07] transition-colors">Cancelar</button>
              <button onClick={eliminar} disabled={eliminando} className="px-5 py-2.5 rounded-[10px] text-sm font-bold text-white disabled:opacity-50 disabled:cursor-not-allowed transition-opacity"
                style={{ background: eliminando ? 'rgba(248,113,113,0.4)' : 'linear-gradient(135deg, #f87171, #ef4444)' }}>
                {eliminando ? 'Eliminando...' : 'Eliminar'}
              </button>
            </div>
          </div>
        </div>
      )}

      {modalNuevo && (
        <ModalNuevoMovimiento subtipo="Deuda" onCerrar={() => setModalNuevo(false)} onGuardado={() => cargar()} />
      )}
    </div>
  )
}

import { useState, useEffect, useMemo } from 'react'
import { useNavigate } from 'react-router-dom'
import { getCategorias, getDependientes } from '../services/api'
import ModalNuevoMovimiento from '../components/Modalnuevomovimiento'
import HeaderModulos from '../components/HeaderModulos'
import { useToast } from '../context/ToastContext'
import { useNotificaciones } from '../context/NotificacionesContext'

// const API = 'http://localhost:3000/api/movimientos'
const API = 'https://david-ekcn.onrender.com/api/movimientos'

const fmt      = (n) => `$${Number(n).toLocaleString('es-CO')}`
const fmtFecha = (f) => {
  if (!f) return '—'
  const [y, m, d] = f.slice(0, 10).split('-')
  return `${d}/${m}/${y}`
}

const inputCls = 'mt-1.5 w-full rounded-xl border border-white/15 bg-white/[0.07] px-3.5 py-2.5 text-sm text-zinc-100 outline-none placeholder:text-zinc-500 focus:border-red-400/60 focus:ring-2 focus:ring-red-400/20'
const selectCls = inputCls 
const labelCls = 'mt-3.5 block text-[0.72rem] font-bold uppercase tracking-[0.06em] text-zinc-400'

export default function ModuloImprevistos() {
  const navigate = useNavigate()
  const usuario  = useMemo(() => { try { return JSON.parse(localStorage.getItem('usuario')) } catch { return null } }, [])
  const { mostrarToast } = useToast()
  const { revisarAhora } = useNotificaciones()

  const [imprevistos, setImprevistos] = useState([])
  const [cargando,    setCargando]    = useState(true)
  const [modalNuevo,  setModalNuevo]  = useState(false)
  const [categorias,  setCategorias]  = useState([])
  const [dependientes,setDependientes]= useState([])
  const [modalEditar, setModalEditar] = useState(null)
  const [confirmarId, setConfirmarId] = useState(null)
  const [guardando,   setGuardando]   = useState(false)
  const [eliminando,  setEliminando]  = useState(false)
  const [errorModal,  setErrorModal]  = useState(null)

  const cargar = () => {
    setCargando(true)
    const token = localStorage.getItem('token')
    fetch(`${API}/imprevistos`, { headers: { Authorization: `Bearer ${token}` }, cache: 'no-store' })
      .then(r => r.json())
      .then(d => { if (Array.isArray(d)) setImprevistos(d) })
      .catch(() => {})
      .finally(() => setCargando(false))
  }

  useEffect(() => {
    cargar()
    getCategorias().then(d => { if (Array.isArray(d)) setCategorias(d) }).catch(() => {})
    getDependientes().then(d => { if (Array.isArray(d)) setDependientes(d) }).catch(() => {})
  }, [])

  const total = useMemo(() => imprevistos.reduce((a, i) => a + Number(i.monto || 0), 0), [imprevistos])

const abrirEditar = (i) => {
  setErrorModal(null)
  setModalEditar({
    id: i.id, monto: String(i.monto),
    causa: i.causa || '',
    fecha_registro: i.fecha ? i.fecha.slice(0, 10) : '',
    id_categoria: i.id_categoria || '',
    id_dependientes: i.id_dependientes || '',
  })
}

  const handleChange = (e) => setModalEditar(p => ({ ...p, [e.target.name]: e.target.value }))

  const guardar = async () => {
    setErrorModal(null)
    if (!modalEditar.monto || isNaN(modalEditar.monto) || Number(modalEditar.monto) <= 0)
      return setErrorModal('El monto debe ser mayor a 0')
    setGuardando(true)
    const token = localStorage.getItem('token')
    try {
      const res = await fetch(`${API}/imprevistos/${modalEditar.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify({
          monto: Number(modalEditar.monto),
          causa: modalEditar.causa || null,
          fecha_registro: modalEditar.fecha_registro || null,
          id_categoria: modalEditar.id_categoria || null,
          id_dependientes: modalEditar.id_dependientes || null,
        }),
      })
      const data = await res.json()
      if (res.ok) {
        mostrarToast('Imprevisto actualizado correctamente')
        revisarAhora()
        setModalEditar(null)
        cargar()
      }
      else setErrorModal(data.mensaje || 'Error al guardar')
    } catch { setErrorModal('Error al conectar con el servidor') }
    finally { setGuardando(false) }
  }

  const eliminar = async () => {
    setEliminando(true)
    const token = localStorage.getItem('token')
    try {
      const res = await fetch(`${API}/imprevistos/${confirmarId}`, { method: 'DELETE', headers: { Authorization: `Bearer ${token}` } })
      if (res.ok) {
        mostrarToast('Imprevisto eliminado correctamente')
        revisarAhora()
        setConfirmarId(null)
        cargar()
      }
    } catch {}
    finally { setEliminando(false) }
  }

  const nombreDep = (id) => {
    if (!id) return null
    const dep = dependientes.find(d => String(d.id_dependientes) === String(id))
    return dep?.Nombre || null
  }

  return (
    <div className="min-h-screen w-full flex flex-col text-white overflow-x-hidden"
      style={{ background: 'radial-gradient(ellipse at 30% 20%, #1e3a5f 10%, #0f172a 60%, #1a0f2e 100%)' }}>

      <HeaderModulos section="Imprevistos" />
      <hr className="my-1 h-px border-0 bg-gradient-to-r from-transparent via-amber-400 to-transparent" />

      <main className="flex-1 flex flex-col w-full max-w-[1400px] mx-auto px-4 py-5 sm:px-6 sm:py-6 md:p-8 gap-6">

        <div>
          <p className="text-sm text-zinc-400">Bienvenido de vuelta</p>
          <h2 className="text-xl sm:text-2xl font-extrabold text-white">{usuario?.nombre || 'Usuario'} <span>👋</span></h2>
        </div>

        {/* Stat card */}
        <article className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 px-5 sm:px-8 py-5 sm:py-6 rounded-2xl border border-white/10"
          style={{ background: 'radial-gradient(ellipse at left, rgba(251,146,60,0.35), rgba(249,115,22,0.04))' }}>
          <div>
            <p className="text-xs font-bold uppercase tracking-widest text-orange-400 mb-1">⚡ Total Imprevistos</p>
            <p className="text-3xl sm:text-4xl font-black text-white">{fmt(total)}</p>
            <p className="text-xs text-zinc-500 mt-1">{imprevistos.length} registro{imprevistos.length !== 1 ? 's' : ''} en total</p>
          </div>
          <button onClick={() => setModalNuevo(true)}
            className="w-full sm:w-auto px-5 py-3 rounded-xl font-bold text-sm text-white transition-all duration-300 hover:-translate-y-px"
            style={{ background: 'linear-gradient(135deg, #fb923c, #f97316)' }}>
            ➕ Registrar Imprevisto
          </button>
        </article>

        {/* Tabla */}
        <section className="w-full rounded-2xl border border-white/10 overflow-hidden shadow-[0_8px_32px_rgba(0,0,0,0.35)]"
          style={{ background: 'rgba(255,255,255,0.04)', backdropFilter: 'blur(16px)' }}>

          <div className="flex items-center justify-between px-5 sm:px-7 py-4 sm:py-5 border-b border-white/[0.08]">
            <h3 className="text-base font-extrabold text-amber-400">📋 Módulo de Imprevistos</h3>
            <span className="text-xs text-zinc-600">{imprevistos.length} registro{imprevistos.length !== 1 ? 's' : ''}</span>
          </div>

          <div className="p-4 sm:p-5">
            {cargando ? (
              <p className="py-8 text-center text-sm italic text-zinc-500 animate-pulse">⏳ Cargando imprevistos...</p>
            ) : imprevistos.length === 0 ? (
              <div className="py-12 flex flex-col items-center gap-3 text-center">
                <span className="text-4xl opacity-30">⚡</span>
                <p className="text-zinc-400 text-sm">No hay imprevistos registrados aún.</p>
                <button onClick={() => setModalNuevo(true)}
                  className="mt-2 px-5 py-2.5 rounded-xl text-sm font-bold text-white"
                  style={{ background: 'linear-gradient(135deg, #fb923c, #f97316)' }}>
                  Registrar primer imprevisto
                </button>
              </div>
            ) : (
              <>
                {/* Mobile cards */}
                <div className="flex flex-col gap-3 md:hidden">
                  {imprevistos.map(i => (
                    <article key={i.id} className="rounded-xl border border-white/10 bg-white/[0.03] p-4">
                      <div className="flex items-start justify-between gap-3">
                        <div className="min-w-0 flex-1">
                          <p className="font-bold text-white truncate">{i.causa || 'Sin causa registrada'}</p>
                          <p className="text-xs text-zinc-500 mt-0.5">{fmtFecha(i.fecha)}</p>
                          {i.categoria && <p className="text-xs text-zinc-500 mt-1">📂 {i.categoria}</p>}
                          {nombreDep(i.id_dependientes) && (
                            <p className="text-xs text-blue-400 mt-1">👤 {nombreDep(i.id_dependientes)}</p>
                          )}
                        </div>
                        <p className="shrink-0 text-base font-black text-orange-400">{fmt(i.monto)}</p>
                      </div>
                      <div className="mt-3 grid grid-cols-2 gap-2">
                        <button onClick={() => abrirEditar(i)} className="rounded-lg border border-blue-400/50 bg-blue-400/10 py-2 text-xs font-bold text-blue-400 hover:bg-blue-400/20 transition-colors">Editar</button>
                        <button onClick={() => setConfirmarId(i.id)} className="rounded-lg border border-red-400/50 bg-red-400/10 py-2 text-xs font-bold text-red-400 hover:bg-red-400/20 transition-colors">Eliminar</button>
                      </div>
                    </article>
                  ))}
                </div>

                {/* Desktop table */}
                <div className="hidden md:block overflow-x-auto">
                  <table className="w-full min-w-[800px] border-collapse text-left">
                    <thead>
                      <tr className="border-b border-white/10">
                        {['Fecha', 'Causa', 'Categoría', 'Dependiente', 'Monto', 'Acciones'].map(col => (
                          <th key={col} className="px-4 py-3 text-xs font-bold uppercase tracking-wider text-zinc-500">{col}</th>
                        ))}
                      </tr>
                    </thead>
                    <tbody>
                      {imprevistos.map(i => (
                        <tr key={i.id} className="border-b border-white/5 hover:bg-white/[0.04] transition-colors">
                          <td className="px-4 py-3 text-sm text-zinc-300">{fmtFecha(i.fecha)}</td>
                          <td className="px-4 py-3 text-sm text-zinc-300 max-w-[200px] truncate">{i.causa || '—'}</td>
                          <td className="px-4 py-3 text-sm text-zinc-300">{i.categoria || '—'}</td>
                          <td className="px-4 py-3 text-sm text-blue-400">{nombreDep(i.id_dependientes) || '—'}</td>
                          <td className="px-4 py-3 text-sm font-extrabold text-orange-400">{fmt(i.monto)}</td>
                          <td className="px-4 py-3">
                            <div className="flex gap-2">
                              <button onClick={() => abrirEditar(i)} className="px-3.5 py-1.5 rounded-lg text-xs font-bold border border-blue-400/50 bg-blue-400/10 text-blue-400 hover:bg-blue-400/20 transition-colors">Editar</button>
                              <button onClick={() => setConfirmarId(i.id)} className="px-3.5 py-1.5 rounded-lg text-xs font-bold border border-red-400/50 bg-red-400/10 text-red-400 hover:bg-red-400/20 transition-colors">Eliminar</button>
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </>
            )}
          </div>
        </section>
      </main>

      <footer className="w-full px-4 py-6 text-center font-mono text-[0.7rem] text-zinc-600">
        <p>© <strong className="text-amber-400">2026 Ahorrapp</strong>. Todos los derechos reservados.</p>
      </footer>

      {/* Modal Editar */}
      {modalEditar && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-4 bg-black/65 backdrop-blur-md">
          <div className="w-full max-w-[460px] rounded-[20px] p-7 border border-white/[0.12] shadow-[0_24px_60px_rgba(0,0,0,0.6)] max-h-[90vh] overflow-y-auto"
            style={{ background: 'rgba(15,23,42,0.95)' }}>
            <h4 className="text-lg font-extrabold text-orange-400 mb-1">✏️ Editar Imprevisto</h4>
            <p className="text-xs text-zinc-500 mb-2">Modifica los campos que necesites y guarda.</p>

            <label className={labelCls}>Monto *</label>
            <input className={inputCls} type="number" name="monto" min="0" step="0.01" value={modalEditar.monto} onChange={handleChange} />

            <label className={labelCls}>Causa</label>
            <input className={inputCls} type="text" name="causa" placeholder="Ej: Reparación, Emergencia médica..." value={modalEditar.causa} onChange={handleChange} />

            <label className={labelCls}>Categoría</label>
            <select
              className={selectCls}
              style={{ colorScheme: 'dark' }}
              name="id_categoria"
              value={modalEditar.id_categoria}
              onChange={handleChange}
            >
              <option value="" style={{ backgroundColor: '#1f2937', color: '#f4f4f5' }}>Sin categoría</option>
              {categorias.filter(c => c.activa == 1).map(c => (
                <option key={c.id} value={c.id} style={{ backgroundColor: '#1f2937', color: '#f4f4f5' }}>
                  {c.nombre}
                </option>
              ))}
            </select>

            <label className={labelCls}>Dependiente</label>
            <select
              className={selectCls}
              style={{ colorScheme: 'dark' }}
              name="id_dependientes"
              value={modalEditar.id_dependientes}
              onChange={handleChange}
            >
              <option value="" style={{ backgroundColor: '#1f2937', color: '#f4f4f5' }}>Ninguno (gasto propio)</option>
              {dependientes.map(d => (
                <option key={d.id_dependientes} value={d.id_dependientes} style={{ backgroundColor: '#1f2937', color: '#f4f4f5' }}>
                  {d.Nombre}
                </option>
              ))}
            </select> 
          

            <label className={labelCls}>Fecha</label>
            <input className={inputCls} type="date" name="fecha_registro" value={modalEditar.fecha_registro} onChange={handleChange} />

            {errorModal && <p className="mt-3 p-[10px_14px] rounded-[10px] bg-red-400/[0.12] border border-red-400/35 text-red-400 text-[0.8rem] font-semibold">{errorModal}</p>}

            <div className="mt-6 flex justify-end gap-2.5">
              <button onClick={() => setModalEditar(null)} className="px-5 py-2.5 rounded-[10px] text-sm font-bold bg-transparent text-zinc-400 border border-white/[0.15] hover:bg-white/[0.07] transition-colors">Cancelar</button>
              <button onClick={guardar} disabled={guardando} className="px-5 py-2.5 rounded-[10px] text-sm font-bold text-white disabled:opacity-50 disabled:cursor-not-allowed transition-opacity"
                style={{ background: guardando ? 'rgba(251,146,60,0.4)' : 'linear-gradient(135deg, #fb923c, #f97316)' }}>
                {guardando ? 'Guardando...' : 'Guardar cambios'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Modal Eliminar */}
      {confirmarId && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-4 bg-black/65 backdrop-blur-md">
          <div className="w-full max-w-[380px] rounded-[20px] p-7 border border-red-400/25 shadow-[0_24px_60px_rgba(0,0,0,0.6)]"
            style={{ background: 'rgba(15,23,42,0.95)' }}>
            <h4 className="text-lg font-extrabold text-red-400 mb-2">🗑️ ¿Eliminar imprevisto?</h4>
            <p className="text-sm text-zinc-400">Esta acción no se puede deshacer.</p>
            <div className="mt-6 flex justify-end gap-2.5">
              <button onClick={() => setConfirmarId(null)} className="px-5 py-2.5 rounded-[10px] text-sm font-bold bg-transparent text-zinc-400 border border-white/[0.15] hover:bg-white/[0.07] transition-colors">Cancelar</button>
              <button onClick={eliminar} disabled={eliminando} className="px-5 py-2.5 rounded-[10px] text-sm font-bold text-white disabled:opacity-50 disabled:cursor-not-allowed transition-opacity"
                style={{ background: eliminando ? 'rgba(248,113,113,0.4)' : 'linear-gradient(135deg, #f87171, #ef4444)' }}>
                {eliminando ? 'Eliminando...' : 'Eliminar'}
              </button>
            </div>
          </div>
        </div>
      )}

      {modalNuevo && (
        <ModalNuevoMovimiento
          subtipo="Imprevisto"
          onCerrar={() => setModalNuevo(false)}
          onGuardado={() => cargar()}
        />
      )}
    </div>
  )
}

import { useState, useEffect } from 'react'
import HeaderModulos from '../components/HeaderModulos'
import { useToast } from '../context/ToastContext'
import {
  getFondoEmergencia,
  crearFondoEmergencia,
  actualizarMetaFondoEmergencia,
  registrarAporteFondo,
  registrarRetiroFondo,
  getMovimientosFondoEmergencia,
} from '../services/api'

const fmt = (n) => `$${Number(n || 0).toLocaleString('es-CO')}`
const fmtFecha = (f) => {
  if (!f) return '—'
  const [y, m, d] = f.slice(0, 10).split('-')
  return `${d}/${m}/${y}`
}

const inputCls = 'mt-1.5 w-full rounded-xl border border-white/15 bg-white/[0.07] px-3.5 py-2.5 text-sm text-zinc-100 outline-none placeholder:text-zinc-500 focus:border-amber-400/60 focus:ring-2 focus:ring-amber-400/20'
const labelCls = 'mt-3.5 block text-[0.72rem] font-bold uppercase tracking-[0.06em] text-zinc-400'

export default function ModuloFondoEmergencia() {
  const { mostrarToast } = useToast()

  const [fondo, setFondo] = useState(null)       // null = todavía no se sabe / no existe
  const [movimientos, setMovimientos] = useState([])
  const [cargando, setCargando] = useState(true)
  const [guardando, setGuardando] = useState(false)
  const [errorModal, setErrorModal] = useState(null)

  // Modales
  const [modalCrear, setModalCrear] = useState(false)
  const [modalMeta, setModalMeta] = useState(false)
  const [modalAporte, setModalAporte] = useState(false)
  const [modalRetiro, setModalRetiro] = useState(false)

  const [metaInput, setMetaInput] = useState('')
  const [montoInput, setMontoInput] = useState('')
  const [descInput, setDescInput] = useState('')

  const cargar = async () => {
    setCargando(true)
    try {
      const [resFondo, resMov] = await Promise.all([
        getFondoEmergencia().catch((e) => (e.message === 'HTTPS 404' ? { ok: false, noExiste: true } : Promise.reject(e))),
        getMovimientosFondoEmergencia().catch(() => ({ ok: false, datos: [] })),
      ])
      if (resFondo?.ok) setFondo(resFondo.datos)
      else setFondo(null)
      setMovimientos(resMov?.datos || [])
    } catch (e) {
      console.error('Error cargando fondo de emergencia:', e)
    } finally {
      setCargando(false)
    }
  }

  useEffect(() => { cargar() }, [])

  const abrirModal = (setter) => { setErrorModal(null); setMontoInput(''); setDescInput(''); setter(true) }
  const cerrarModales = () => { setModalCrear(false); setModalMeta(false); setModalAporte(false); setModalRetiro(false); setErrorModal(null) }

  // ── Crear fondo ──
  const handleCrear = async () => {
    const meta = Number(metaInput)
    if (!metaInput || Number.isNaN(meta) || meta < 0) return setErrorModal('Ingresa una meta válida')
    setGuardando(true)
    try {
      const data = await crearFondoEmergencia(meta)
      if (data.ok) {
        mostrarToast('Fondo de emergencia creado')
        setModalCrear(false)
        cargar()
      } else setErrorModal(data.mensaje || 'Error al crear el fondo')
    } catch { setErrorModal('Error al conectar con el servidor') }
    finally { setGuardando(false) }
  }

  // ── Editar meta ──
  const handleEditarMeta = async () => {
    const meta = Number(metaInput)
    if (metaInput === '' || Number.isNaN(meta) || meta < 0) return setErrorModal('Ingresa una meta válida')
    setGuardando(true)
    try {
      const data = await actualizarMetaFondoEmergencia(meta)
      if (data.ok) {
        mostrarToast('Meta actualizada')
        setModalMeta(false)
        cargar()
      } else setErrorModal(data.mensaje || 'Error al actualizar la meta')
    } catch { setErrorModal('Error al conectar con el servidor') }
    finally { setGuardando(false) }
  }

  // ── Aportar ──
  const handleAporte = async () => {
    const monto = Number(montoInput)
    if (!montoInput || Number.isNaN(monto) || monto <= 0) return setErrorModal('El monto debe ser mayor a 0')
    setGuardando(true)
    try {
      const data = await registrarAporteFondo(monto, descInput.trim() || null)
      if (data.ok) {
        mostrarToast('Aporte registrado')
        setModalAporte(false)
        cargar()
      } else setErrorModal(data.mensaje || 'Error al registrar el aporte')
    } catch { setErrorModal('Error al conectar con el servidor') }
    finally { setGuardando(false) }
  }

  // ── Retirar ──
  const handleRetiro = async () => {
    const monto = Number(montoInput)
    if (!montoInput || Number.isNaN(monto) || monto <= 0) return setErrorModal('El monto debe ser mayor a 0')
    if (fondo && monto > Number(fondo.saldo_actual)) return setErrorModal('El retiro no puede ser mayor al saldo disponible')
    setGuardando(true)
    try {
      const data = await registrarRetiroFondo(monto, descInput.trim() || null)
      if (data.ok) {
        mostrarToast('Retiro registrado')
        setModalRetiro(false)
        cargar()
      } else setErrorModal(data.mensaje || 'Error al registrar el retiro')
    } catch { setErrorModal('Error al conectar con el servidor') }
    finally { setGuardando(false) }
  }

  const saldo = Number(fondo?.saldo_actual || 0)
  const meta = Number(fondo?.meta || 0)
  const porcentaje = meta > 0 ? Math.min(100, (saldo / meta) * 100) : 0

  return (
    <div className="min-h-screen w-full flex flex-col text-white overflow-x-hidden"
      style={{ background: 'radial-gradient(ellipse at 30% 20%, #1e3a5f 10%, #0f172a 60%, #1a0f2e 100%)' }}>

      <HeaderModulos section="Fondo de Emergencia" />
      <hr className="my-1 h-px border-0 bg-gradient-to-r from-transparent via-amber-400 to-transparent" />

      <main className="flex-1 flex flex-col w-full max-w-[1400px] mx-auto px-4 py-5 sm:px-6 sm:py-6 md:p-8 gap-6">

        {cargando ? (
          <p className="text-sm text-zinc-400">Cargando...</p>

        ) : !fondo ? (
          // ── Sin fondo configurado todavía ──
          <div className="rounded-2xl border border-white/10 bg-white/[0.04] p-8 text-center">
            <p className="text-4xl mb-3">🛡️</p>
            <h2 className="text-lg font-extrabold text-zinc-100">Todavía no tienes un fondo de emergencia</h2>
            <p className="mt-2 text-sm text-zinc-400 max-w-md mx-auto">
              Un fondo de emergencia es dinero apartado para imprevistos grandes (pérdida de trabajo, salud, reparaciones urgentes).
              Definí una meta de ahorro para empezar.
            </p>
            <button
              onClick={() => abrirModal(setModalCrear)}
              className="mt-5 rounded-xl bg-gradient-to-br from-amber-400 to-orange-500 px-6 py-2.5 text-sm font-bold text-slate-900"
            >
              Crear fondo de emergencia
            </button>
          </div>

        ) : (
          <>
            {/* ── Resumen ── */}
            <section className="rounded-2xl border border-white/10 p-6"
              style={{ background: 'radial-gradient(ellipse at left, rgba(251,191,36,0.25), rgba(251,191,36,0.03))' }}>
              <div className="flex flex-wrap items-start justify-between gap-4">
                <div>
                  <p className="text-xs font-bold uppercase tracking-wider text-zinc-400">Saldo actual</p>
                  <p className="mt-1 text-3xl font-black text-amber-300">{fmt(saldo)}</p>
                  <p className="mt-1 text-xs text-zinc-500">Meta: {fmt(meta)} · Creado el {fmtFecha(fondo.fecha_creacion)}</p>
                </div>
                <button
                  onClick={() => { setMetaInput(String(meta)); abrirModal(setModalMeta) }}
                  className="rounded-lg border border-white/15 bg-white/5 px-3.5 py-1.5 text-xs font-bold text-zinc-300 hover:bg-white/10"
                >
                  Editar meta
                </button>
              </div>

              <div className="mt-4 h-3 w-full rounded-full bg-white/10 overflow-hidden">
                <div
                  className="h-full rounded-full bg-gradient-to-r from-amber-400 to-orange-500 transition-all"
                  style={{ width: `${porcentaje}%` }}
                />
              </div>
              <p className="mt-1.5 text-xs text-zinc-400">{porcentaje.toFixed(1)}% de la meta</p>

              <div className="mt-5 flex flex-wrap gap-3">
                <button
                  onClick={() => abrirModal(setModalAporte)}
                  className="rounded-xl bg-gradient-to-br from-emerald-400 to-emerald-500 px-5 py-2.5 text-sm font-bold text-slate-900"
                >
                  + Aportar
                </button>
                <button
                  onClick={() => abrirModal(setModalRetiro)}
                  disabled={saldo <= 0}
                  className="rounded-xl border border-red-400/50 bg-red-400/10 px-5 py-2.5 text-sm font-bold text-red-400 hover:bg-red-400/20 disabled:opacity-40 disabled:cursor-not-allowed"
                >
                  − Retirar
                </button>
              </div>
            </section>

            {/* ── Historial de movimientos ── */}
            <section>
              <p className="mb-3 text-xs font-bold uppercase tracking-wider text-zinc-500">
                Movimientos ({movimientos.length})
              </p>

              {movimientos.length === 0 ? (
                <p className="text-sm text-zinc-500">Todavía no registraste aportes ni retiros.</p>
              ) : (
                <div className="grid gap-2.5">
                  {movimientos.map((m) => (
                    <div
                      key={m.id_movimiento_fondo}
                      className="flex items-center justify-between rounded-xl border border-white/10 bg-white/[0.04] px-4 py-3"
                    >
                      <div className="flex items-center gap-3">
                        <span className={`flex h-8 w-8 items-center justify-center rounded-full text-sm ${
                          m.tipo === 'aporte' ? 'bg-emerald-400/15 text-emerald-400' : 'bg-red-400/15 text-red-400'
                        }`}>
                          {m.tipo === 'aporte' ? '+' : '−'}
                        </span>
                        <div>
                          <p className="text-sm font-bold text-zinc-100 capitalize">{m.tipo}</p>
                          <p className="text-xs text-zinc-500">{m.descripcion || 'Sin descripción'} · {fmtFecha(m.fecha_registro)}</p>
                        </div>
                      </div>
                      <p className={`text-sm font-bold ${m.tipo === 'aporte' ? 'text-emerald-400' : 'text-red-400'}`}>
                        {m.tipo === 'aporte' ? '+' : '−'}{fmt(m.monto)}
                      </p>
                    </div>
                  ))}
                </div>
              )}
            </section>
          </>
        )}
      </main>

      {/* ── Modal: Crear fondo ── */}
      {modalCrear && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center bg-black/70 p-4 backdrop-blur-md">
          <div className="w-full max-w-[420px] rounded-2xl border border-white/10 bg-slate-950/95 p-6 shadow-2xl sm:p-7">
            <h4 className="text-lg font-extrabold text-amber-400">🛡️ Crear Fondo de Emergencia</h4>
            <label className={labelCls}>Meta de ahorro *</label>
            <input className={inputCls} type="number" min="0" placeholder="Ej: 3000000"
              value={metaInput} onChange={(e) => setMetaInput(e.target.value)} disabled={guardando} />
            {errorModal && <p className="mt-3 text-xs font-semibold text-red-400">{errorModal}</p>}
            <div className="mt-6 flex flex-col-reverse gap-2 sm:flex-row sm:justify-end">
              <button onClick={cerrarModales} disabled={guardando}
                className="rounded-xl border border-white/15 bg-transparent px-5 py-2.5 text-sm font-bold text-zinc-400 hover:bg-white/10 disabled:opacity-50">
                Cancelar
              </button>
              <button onClick={handleCrear} disabled={guardando}
                className="rounded-xl bg-gradient-to-br from-amber-400 to-orange-500 px-5 py-2.5 text-sm font-bold text-slate-900 disabled:opacity-50">
                {guardando ? 'Creando...' : 'Crear'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ── Modal: Editar meta ── */}
      {modalMeta && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center bg-black/70 p-4 backdrop-blur-md">
          <div className="w-full max-w-[420px] rounded-2xl border border-white/10 bg-slate-950/95 p-6 shadow-2xl sm:p-7">
            <h4 className="text-lg font-extrabold text-amber-400">✏️ Editar meta</h4>
            <label className={labelCls}>Nueva meta *</label>
            <input className={inputCls} type="number" min="0"
              value={metaInput} onChange={(e) => setMetaInput(e.target.value)} disabled={guardando} />
            {errorModal && <p className="mt-3 text-xs font-semibold text-red-400">{errorModal}</p>}
            <div className="mt-6 flex flex-col-reverse gap-2 sm:flex-row sm:justify-end">
              <button onClick={cerrarModales} disabled={guardando}
                className="rounded-xl border border-white/15 bg-transparent px-5 py-2.5 text-sm font-bold text-zinc-400 hover:bg-white/10 disabled:opacity-50">
                Cancelar
              </button>
              <button onClick={handleEditarMeta} disabled={guardando}
                className="rounded-xl bg-gradient-to-br from-amber-400 to-orange-500 px-5 py-2.5 text-sm font-bold text-slate-900 disabled:opacity-50">
                {guardando ? 'Guardando...' : 'Guardar'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ── Modal: Aportar ── */}
      {modalAporte && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center bg-black/70 p-4 backdrop-blur-md">
          <div className="w-full max-w-[420px] rounded-2xl border border-white/10 bg-slate-950/95 p-6 shadow-2xl sm:p-7">
            <h4 className="text-lg font-extrabold text-emerald-400">+ Registrar aporte</h4>
            <label className={labelCls}>Monto *</label>
            <input className={inputCls} type="number" min="0" placeholder="Ej: 100000"
              value={montoInput} onChange={(e) => setMontoInput(e.target.value)} disabled={guardando} />
            <label className={labelCls}>Descripción</label>
            <input className={inputCls} type="text" placeholder="Opcional"
              value={descInput} onChange={(e) => setDescInput(e.target.value)} disabled={guardando} />
            {errorModal && <p className="mt-3 text-xs font-semibold text-red-400">{errorModal}</p>}
            <div className="mt-6 flex flex-col-reverse gap-2 sm:flex-row sm:justify-end">
              <button onClick={cerrarModales} disabled={guardando}
                className="rounded-xl border border-white/15 bg-transparent px-5 py-2.5 text-sm font-bold text-zinc-400 hover:bg-white/10 disabled:opacity-50">
                Cancelar
              </button>
              <button onClick={handleAporte} disabled={guardando}
                className="rounded-xl bg-gradient-to-br from-emerald-400 to-emerald-500 px-5 py-2.5 text-sm font-bold text-slate-900 disabled:opacity-50">
                {guardando ? 'Guardando...' : 'Aportar'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ── Modal: Retirar ── */}
      {modalRetiro && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center bg-black/70 p-4 backdrop-blur-md">
          <div className="w-full max-w-[420px] rounded-2xl border border-white/10 bg-slate-950/95 p-6 shadow-2xl sm:p-7">
            <h4 className="text-lg font-extrabold text-red-400">− Registrar retiro</h4>
            <p className="mt-1 text-xs text-zinc-500">Saldo disponible: {fmt(saldo)}</p>
            <label className={labelCls}>Monto *</label>
            <input className={inputCls} type="number" min="0" max={saldo} placeholder="Ej: 50000"
              value={montoInput} onChange={(e) => setMontoInput(e.target.value)} disabled={guardando} />
            <label className={labelCls}>Descripción</label>
            <input className={inputCls} type="text" placeholder="Opcional"
              value={descInput} onChange={(e) => setDescInput(e.target.value)} disabled={guardando} />
            {errorModal && <p className="mt-3 text-xs font-semibold text-red-400">{errorModal}</p>}
            <div className="mt-6 flex flex-col-reverse gap-2 sm:flex-row sm:justify-end">
              <button onClick={cerrarModales} disabled={guardando}
                className="rounded-xl border border-white/15 bg-transparent px-5 py-2.5 text-sm font-bold text-zinc-400 hover:bg-white/10 disabled:opacity-50">
                Cancelar
              </button>
              <button onClick={handleRetiro} disabled={guardando}
                className="rounded-xl border border-red-400/50 bg-red-400/10 px-5 py-2.5 text-sm font-bold text-red-400 hover:bg-red-400/20 disabled:opacity-50">
                {guardando ? 'Guardando...' : 'Retirar'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

import { useState, useEffect } from 'react'
import HeaderModulos from '../components/HeaderModulos'
import { useToast } from '../context/ToastContext'
import { useNotificaciones } from '../context/NotificacionesContext'
// activar SOLO si se utilizan mas adelante
// import { useNavigate, useLocation } from 'react-router-dom'

import {
  getCategorias,
  crearCategoria,
  editarCategoria,
  deshabilitarCategoria,
  habilitarCategoria,
  eliminarCategoria,
  getGastosPorCategoria,
  getIngresosPorCategoria,
  getAhorrosPorCategoria,
  getImprevistosPorCategoria,
  getDeudasPorCategoria,
} from '../services/api'


// Límites de validación para los campos del formulario de categorías.
const NOMBRE_MAX_LENGTH = 50
const NOMBRE_MIN_LENGTH = 2
const DESCRIPCION_MAX_LENGTH = 200

let usuario = null
try {
  usuario = JSON.parse(localStorage.getItem('usuario'))
} catch {
  usuario = null
}

export default function ModuloCategorias() {

  // activas SOLO si se usan mas adelante
  // const navigate = useNavigate()
  // const location = useLocation()
  const { mostrarToast } = useToast()
  const { revisarAhora } = useNotificaciones()

  const [categorias, setCategorias] = useState([])
  const [modalAgregar, setModalAgregar] = useState(false)
  const [modalEditar, setModalEditar] = useState(false)
  const [categoriaEdit, setCategoriaEdit] = useState(null)
  const [formNombre, setFormNombre] = useState('')
  const [formDesc, setFormDesc] = useState('')
  // evita doble envío del formulario (doble clic / doble submit)
  const [guardando, setGuardando] = useState(false)
// agregado pero no revizado, verificar funcionalidad
  const [menuOpen, setMenuOpen] = useState(false)

  // desactivado con el fin de realizar pruebas
  // useEffect(() => {
  //   getCategorias()
  //     .then(data => {
  //       if (Array.isArray(data)) setCategorias(data)
  //     })
  //     .catch(() => {})
  // }, [])

  // remplaza la funcion anteriormente comentada, en caso de error realizar pruebas
  useEffect(() => {
  Promise.all([
    getGastosPorCategoria(),
    getIngresosPorCategoria(),
    getAhorrosPorCategoria(),
    getImprevistosPorCategoria(),
    getDeudasPorCategoria(),
  ])
    .then(([gastos, ingresos, ahorros, imprevistos, deudas]) => {
      if (!Array.isArray(gastos)) return

      const combinadas = gastos.map(cat => {
        const ing = ingresos.find(c => c.id === cat.id)
        const aho = ahorros.find(c => c.id === cat.id)
        const imp = imprevistos.find(c => c.id === cat.id)
        const deu = deudas.find(c => c.id === cat.id)

        return {
          ...cat,
          total_movimientos:
            Number(cat.total_gastos || 0) +
            Number(ing?.total_ingresos || 0) +
            Number(aho?.total_ahorros || 0) +
            Number(imp?.total_imprevistos || 0) +
            Number(deu?.total_deudas || 0),
        }
      })

      setCategorias(combinadas)
    })
    .catch(error => {
      console.error('Error al cargar categorías combinadas:', error)
    })
}, [])

  const activas = categorias.filter(c => c.activa == 1 || c.activa === true)
  const inactivas = categorias.filter(c => c.activa == 0 || c.activa === false)

  const esSistema = cat =>
    cat.es_global == 1 || cat.es_global === true ||
    cat.sistema == 1 || cat.sistema === true

  const handleAgregar = async () => {
    const nombre = formNombre.trim()
    const descripcion = formDesc.trim()

    if (!nombre) return alert('El nombre es obligatorio')
    if (nombre.length < NOMBRE_MIN_LENGTH || nombre.length > NOMBRE_MAX_LENGTH) {
      return alert(`El nombre debe tener entre ${NOMBRE_MIN_LENGTH} y ${NOMBRE_MAX_LENGTH} caracteres`)
    }
    if (descripcion.length > DESCRIPCION_MAX_LENGTH) {
      return alert(`La descripción no puede superar los ${DESCRIPCION_MAX_LENGTH} caracteres`)
    }
    const yaExiste = categorias.some(
      c => c.nombre.trim().toLowerCase() === nombre.toLowerCase()
    )
    if (yaExiste) return alert('Ya existe una categoría con ese nombre (si esta deshabilitada considera habilitarla)')    
    if (guardando) return // evita doble envío si ya hay una petición en curso

    setGuardando(true)
    try {
      const respuesta = await crearCategoria({
        nombre,
        descripcion,
      })

      if (respuesta.ok) {
        mostrarToast('Categoría registrada correctamente')
        setCategorias(prev => [
          ...prev,
          {
            id: respuesta.id,
            nombre,
            descripcion,
            activa: true,
            sistema: false,
            es_global: false,
            total_movimientos: 0,
          },
        ])
        setFormNombre('')
        setFormDesc('')
        setModalAgregar(false)
      } else {
        alert(respuesta.mensaje || 'Error al crear la categoría')
      }
    } catch (error) {
      alert(error.message || 'Error al crear la categoría')
    } finally {
      setGuardando(false)
    }
  }

  const abrirEditar = cat => {
    setCategoriaEdit({ ...cat })
    setModalEditar(true)
  }

  const handleGuardarEdicion = async () => {
    const nombre = (categoriaEdit.nombre || '').trim()
    const descripcion = (categoriaEdit.descripcion || '').trim()

    if (!nombre) return alert('El nombre es obligatorio')
    if (nombre.length < NOMBRE_MIN_LENGTH || nombre.length > NOMBRE_MAX_LENGTH) {
      return alert(`El nombre debe tener entre ${NOMBRE_MIN_LENGTH} y ${NOMBRE_MAX_LENGTH} caracteres`)
    }
    if (descripcion.length > DESCRIPCION_MAX_LENGTH) {
      return alert(`La descripción no puede superar los ${DESCRIPCION_MAX_LENGTH} caracteres`)
    }
    const yaExiste = categorias.some(
      c => c.id !== categoriaEdit.id && c.nombre.trim().toLowerCase() === nombre.toLowerCase()
    )
    if (yaExiste) return alert('Ya existe una categoría con ese nombre (activa o deshabilitada)')
    if (guardando) return // evita doble envío si ya hay una petición en curso

    setGuardando(true)
    try {
      const respuesta = await editarCategoria(categoriaEdit.id, {
        nombre,
        descripcion,
      })

      if (respuesta.ok) {
        mostrarToast('Categoría actualizada correctamente')
        setCategorias(prev =>
          prev.map(c => (c.id === categoriaEdit.id ? { ...c, ...categoriaEdit, nombre, descripcion } : c))
        )
        setModalEditar(false)
      } else {
        alert(respuesta.mensaje || 'Error al editar la categoría')
      }
    } catch (error) {
      alert(error.message || 'Error al editar la categoría')
    } finally {
      setGuardando(false)
    }
  }

  const handleDeshabilitar = async id => {
    if (!window.confirm('¿Seguro que deseas deshabilitar esta categoría?')) return

    try {
      const respuesta = await deshabilitarCategoria(id)

      if (respuesta.ok) {
        mostrarToast('Categoría deshabilitada correctamente')
        setCategorias(prev =>
          prev.map(c => (c.id === id ? { ...c, activa: false } : c))
        )
      } else {
        alert(respuesta.mensaje || 'Error al deshabilitar la categoría')
      }
    } catch (error) {
      alert(error.message || 'Error al deshabilitar la categoría')
    }
  }

  const handleHabilitar = async id => {
    try {
      const respuesta = await habilitarCategoria(id)

      if (respuesta.ok) {
        mostrarToast('Categoría habilitada correctamente')
        setCategorias(prev =>
          prev.map(c => (c.id === id ? { ...c, activa: true } : c))
        )
      } else {
        alert(respuesta.mensaje || 'Error al habilitar la categoría')
      }
    } catch (error) {
      alert(error.message || 'Error al habilitar la categoría')
    }
    
  }

  const handleEliminar = async id => {
    if (!window.confirm('¿Eliminar esta categoría permanentemente? Esta acción no se puede deshacer.')) return
    try {
      const respuesta = await eliminarCategoria(id)
      if (respuesta.ok) {
        mostrarToast('Categoría eliminada')
        setCategorias(prev => prev.filter(c => c.id !== id))
      } else {
        alert(respuesta.mensaje || 'Error al eliminar la categoría')
      }
    } catch (error) {
      alert(error.message || 'Error al eliminar la categoría')
    }
  }

  const navButtonClass = isActive =>
    isActive
      ? 'w-full md:w-auto flex items-center gap-2 px-4 py-3 md:px-3 md:py-2 rounded-xl md:rounded-[10px] text-left font-bold text-amber-300 bg-amber-400/20 border border-amber-400/50 shadow-[0_0_12px_rgba(251,191,36,0.4)] transition-all'
      : 'w-full md:w-auto flex items-center gap-2 px-4 py-3 md:px-3 md:py-2 rounded-xl md:rounded-[10px] text-left font-semibold text-white bg-white/10 border border-white/5 hover:-translate-y-px hover:shadow-[0_1px_8px_rgba(255,187,0,0.4)] transition-all'

  const inputClass =
    'mt-2 w-full rounded-xl border border-white/15 bg-white/10 px-4 py-2.5 text-sm text-zinc-100 outline-none placeholder:text-zinc-500 focus:border-amber-400/60 focus:ring-2 focus:ring-amber-400/20'

  const labelClass =
    'mt-4 block text-xs font-bold uppercase tracking-wider text-zinc-400'

  const formatMoney = value =>
    new Intl.NumberFormat('es-CO', {
      style: 'currency',
      currency: 'COP',
      maximumFractionDigits: 0,
    }).format(Number(value || 0))

  const closeModal = () => {
    setModalAgregar(false)
    setModalEditar(false)
    setCategoriaEdit(null)
    setFormNombre('')
    setFormDesc('')
  }

  return (
    <div className="min-h-screen w-full overflow-x-hidden text-white [background:radial-gradient(ellipse_at_30%_20%,#1e3a5f_10%,#0f172a_60%,#1a0f2e_100%)]">
      {/* HEADER */}
      <HeaderModulos section="Categorías" />

      <hr className="my-1 h-px border-0 bg-gradient-to-r from-transparent via-amber-400 to-transparent" />

      <main className="mx-auto flex w-full max-w-[1400px] flex-1 flex-col gap-5 px-4 py-5 sm:px-6 sm:py-6 md:gap-6 md:p-8">
        <div>
          <p className="text-sm text-zinc-400">Bienvenido de vuelta</p>
          <h2 className="text-xl sm:text-2xl font-extrabold text-white">{usuario?.nombre || 'Usuario'} <span>👋</span></h2>
        </div>

        <article className="flex flex-col justify-between gap-4 rounded-2xl border border-white/10 bg-[radial-gradient(ellipse_at_left,rgba(16,185,129,0.25),rgba(5,150,105,0.04))] px-5 py-5 sm:flex-row sm:items-center sm:px-8 sm:py-6">
          <div>
            <p className="mb-1 text-xs font-bold uppercase tracking-wider text-emerald-400">
              🧩 Categorías activas
            </p>
            <p className="text-3xl font-black text-white">{activas.length}</p>
          </div>

          <button
            onClick={() => setModalAgregar(true)}
            className="w-full rounded-xl bg-gradient-to-br from-emerald-400 to-emerald-500 px-5 py-3 text-sm font-bold text-slate-900 transition-all duration-300 hover:-translate-y-px sm:w-auto"
          >
            + Agregar Categoría
          </button>
        </article>

        <section className="overflow-hidden rounded-2xl border border-white/10 bg-white/[0.04] shadow-2xl backdrop-blur-lg">
          <div className="border-b border-white/10 px-5 py-4 sm:px-7 sm:py-5">
            <h3 className="text-base font-extrabold text-amber-400">
              📋 Módulo de Categorías
            </h3>
          </div>

          <div className="p-4 sm:p-5">
            {activas.length === 0 ? (
              <p className="py-5 text-sm italic text-zinc-500">
                No hay categorías activas.
              </p>
            ) : (
              <>
                <div className="grid gap-3 md:hidden">
                  {activas.map(cat => (
                    <article key={cat.id} className="rounded-2xl border border-white/10 bg-white/[0.05] p-4">
                      <div className="flex items-start justify-between gap-3">
                        <div className="min-w-0">
                          <h4 className="break-words text-sm font-bold text-zinc-100">
                            {cat.nombre}
                          </h4>
                          <p className="mt-1 break-words text-sm text-zinc-400">
                            {cat.descripcion || 'Sin descripción'}
                          </p>

                          {/* funcion nueva agregada, realizar pruebasy solo es valida si anteriormente se definio el useEffect "total_movimientos" */}
                          <div className="mt-3 rounded-xl border border-white/10 bg-white/[0.04] px-3 py-2 text-xs">
                            <p className="text-zinc-500">Total movimientos</p>
                            <p className="font-bold text-amber-300">
                              {formatMoney(cat.total_movimientos)}
                            </p>
                          </div>

                        </div>

                        <span className={`shrink-0 rounded-full border px-2.5 py-1 text-[0.68rem] font-bold ${
                          cat.es_global
                            ? 'border-emerald-400/40 bg-emerald-400/15 text-emerald-400'
                            : 'border-indigo-400/40 bg-indigo-400/15 text-indigo-300'
                        }`}>
                          {cat.es_global ? 'Sistema' : 'Personal'}
                        </span>
                      </div>

                      {!esSistema(cat) && (
                        <div className="mt-4 grid grid-cols-1 gap-2 sm:grid-cols-2">
                          <button
                            onClick={() => abrirEditar(cat)}
                            className="rounded-lg border border-emerald-400/50 bg-emerald-400/10 px-4 py-2 text-sm font-bold text-emerald-400"
                          >
                            Editar
                          </button>
                          <button
                            onClick={() => handleDeshabilitar(cat.id)}
                            className="rounded-lg border border-orange-400/50 bg-orange-400/10 px-4 py-2 text-sm font-bold text-orange-400"
                          >
                            Deshabilitar
                          </button>
                        </div>
                      )}
                    </article>
                  ))}
                </div>

                {/* TABLA DESKTOP */}
                <div className="hidden overflow-x-auto md:block">
                  <table className="w-full min-w-[760px] border-collapse text-left">
                    <thead>
                      <tr className="border-b border-white/10">
                        {['Nombre', 'Descripción', 'Tipo', 'Total movimientos', 'Acciones'].map(col => (
                          <th key={col} className="px-4 py-3 text-xs font-bold uppercase tracking-wider text-zinc-500">
                            {col}
                          </th>
                        ))}
                      </tr>
                    </thead>
                    <tbody>
                      {activas.map(cat => (
                        <tr key={cat.id} className="border-b border-white/5 transition-colors hover:bg-white/[0.04]">
                          <td className="px-4 py-3 text-sm font-bold text-zinc-100">{cat.nombre}</td>
                          <td className="px-4 py-3 text-sm text-zinc-400">{cat.descripcion || '—'}</td>
                          <td className="px-4 py-3">
                            <span className={`rounded-full border px-3 py-1 text-xs font-bold ${
                              cat.es_global
                                ? 'border-emerald-400/40 bg-emerald-400/15 text-emerald-400'
                                : 'border-indigo-400/40 bg-indigo-400/15 text-indigo-300'
                            }`}>
                              {cat.es_global ? 'Sistema' : 'Personalizada'}
                            </span>
                          </td>
                          <td className="px-4 py-3 text-sm font-bold text-amber-300">
                            {formatMoney(cat.total_movimientos)}
                          </td>
                          <td className="px-4 py-3">
                            {!esSistema(cat) && (
                              <div className="flex gap-2">
                                <button
                                  onClick={() => abrirEditar(cat)}
                                  className="rounded-lg border border-emerald-400/50 bg-emerald-400/10 px-4 py-1.5 text-xs font-bold text-emerald-400 hover:bg-emerald-400/20"
                                >
                                  Editar
                                </button>
                                <button
                                  onClick={() => handleDeshabilitar(cat.id)}
                                  className="rounded-lg border border-orange-400/50 bg-orange-400/10 px-4 py-1.5 text-xs font-bold text-orange-400 hover:bg-orange-400/20"
                                >
                                  Deshabilitar
                                </button>
                              </div>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </>
            )}

            {inactivas.length > 0 && (
              <div className="mt-8 opacity-70">
                <p className="mb-3 text-xs font-bold uppercase tracking-wider text-zinc-500">
                  Categorías deshabilitadas ({inactivas.length})
                </p>

                <div className="grid gap-3 md:hidden">
                  {inactivas.map(cat => (
                    <article key={cat.id} className="rounded-2xl border border-white/10 bg-white/[0.04] p-4">
                      <p className="text-sm font-bold text-zinc-500 line-through">{cat.nombre}</p>
                      <p className="mt-1 text-sm text-zinc-600">{cat.descripcion || 'Sin descripción'}</p>
                      <td className="px-4 py-3 text-right">
                      <button
                        onClick={() => handleHabilitar(cat.id)}
                        className="rounded-lg border border-emerald-400/40 bg-emerald-400/10 px-4 py-1.5 text-xs font-bold text-emerald-400"
                      >
                        Habilitar
                      </button>
                      <button
                        onClick={() => handleEliminar(cat.id)}
                        className="ml-2 rounded-lg border border-red-400/40 bg-red-400/10 px-4 py-1.5 text-xs font-bold text-red-400"
                      >
                        Eliminar
                      </button>
                    </td>
                    </article>
                  ))}
                </div>

                <div className="hidden overflow-x-auto md:block">
                  <table className="w-full min-w-[620px] border-collapse text-left">
                    <tbody>
                      {inactivas.map(cat => (
                        <tr key={cat.id} className="border-b border-white/5">
                          <td className="px-4 py-3 text-sm text-zinc-500 line-through">{cat.nombre}</td>
                          <td className="px-4 py-3 text-sm text-zinc-600">{cat.descripcion || '—'}</td>
                          <td className="px-4 py-3 text-right">
                            <button
                              onClick={() => handleHabilitar(cat.id)}
                              className="rounded-lg border border-emerald-400/40 bg-emerald-400/10 px-4 py-1.5 text-xs font-bold text-emerald-400"
                            >
                              Habilitar
                            </button>
                            <button
                              onClick={() => handleEliminar(cat.id)}
                              className="ml-2 rounded-lg border border-red-400/40 bg-red-400/10 px-4 py-1.5 text-xs font-bold text-red-400"
                            >
                              Eliminar
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}
          </div>
        </section>
      </main>

      <footer className="w-full px-4 py-6 text-center font-mono text-[0.7rem] text-zinc-600">
        <p>© <strong className="text-amber-400">2026 Ahorrapp</strong>. Todos los derechos reservados.</p>
      </footer>

      {modalAgregar && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center bg-black/70 p-4 backdrop-blur-md">
          <div className="w-full max-w-[420px] rounded-2xl border border-white/10 bg-slate-950/95 p-6 shadow-2xl sm:p-7">
            <h4 className="text-lg font-extrabold text-amber-400">🧩 Nueva Categoría</h4>

            <label className={labelClass}>Nombre *</label>
            <input
              className={inputClass}
              type="text"
              placeholder="Ej: Ropa, Mascotas..."
              value={formNombre}
              onChange={e => setFormNombre(e.target.value)}
              required
              minLength={NOMBRE_MIN_LENGTH}
              maxLength={NOMBRE_MAX_LENGTH}
              disabled={guardando}
            />

            <label className={labelClass}>Descripción</label>
            <input
              className={inputClass}
              type="text"
              placeholder="Descripción opcional"
              value={formDesc}
              onChange={e => setFormDesc(e.target.value)}
              maxLength={DESCRIPCION_MAX_LENGTH}
              disabled={guardando}
            />

            <div className="mt-6 flex flex-col-reverse gap-2 sm:flex-row sm:justify-end">
              <button
                onClick={closeModal}
                disabled={guardando}
                className="rounded-xl border border-white/15 bg-transparent px-5 py-2.5 text-sm font-bold text-zinc-400 hover:bg-white/10 disabled:opacity-50"
              >
                Cancelar
              </button>
              <button
                onClick={handleAgregar}
                disabled={guardando}
                className="rounded-xl bg-gradient-to-br from-emerald-400 to-emerald-500 px-5 py-2.5 text-sm font-bold text-slate-900 disabled:opacity-50"
              >
                {guardando ? 'Guardando...' : 'Guardar'}
              </button>
            </div>
          </div>
        </div>
      )}

      {modalEditar && categoriaEdit && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center bg-black/70 p-4 backdrop-blur-md">
          <div className="w-full max-w-[420px] rounded-2xl border border-white/10 bg-slate-950/95 p-6 shadow-2xl sm:p-7">
            <h4 className="text-lg font-extrabold text-amber-400">✏️ Editar Categoría</h4>

            <label className={labelClass}>Nombre *</label>
            <input
              className={inputClass}
              type="text"
              value={categoriaEdit.nombre}
              onChange={e => setCategoriaEdit(prev => ({ ...prev, nombre: e.target.value }))}
              required
              minLength={NOMBRE_MIN_LENGTH}
              maxLength={NOMBRE_MAX_LENGTH}
              disabled={guardando}
            />

            <label className={labelClass}>Descripción</label>
            <input
              className={inputClass}
              type="text"
              value={categoriaEdit.descripcion || ''}
              onChange={e => setCategoriaEdit(prev => ({ ...prev, descripcion: e.target.value }))}
              maxLength={DESCRIPCION_MAX_LENGTH}
              disabled={guardando}
            />

            <div className="mt-6 flex flex-col-reverse gap-2 sm:flex-row sm:justify-end">
              <button
                onClick={closeModal}
                disabled={guardando}
                className="rounded-xl border border-white/15 bg-transparent px-5 py-2.5 text-sm font-bold text-zinc-400 hover:bg-white/10 disabled:opacity-50"
              >
                Cancelar
              </button>
              <button
                onClick={handleGuardarEdicion}
                disabled={guardando}
                className="rounded-xl bg-gradient-to-br from-emerald-400 to-emerald-500 px-5 py-2.5 text-sm font-bold text-slate-900 disabled:opacity-50"
              >
                {guardando ? 'Guardando...' : 'Guardar cambios'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

import { useState, useEffect } from 'react'
import { useNavigate, useLocation } from 'react-router-dom'
import HeaderModulos from '../components/HeaderModulos'
import InfoDependientes from '../components/modals/InfoDependientes'
import { useToast } from '../context/ToastContext'
import { useNotificaciones } from '../context/NotificacionesContext'
import { API_URL } from '../services/api'


let usuario = null
try {
  usuario = JSON.parse(localStorage.getItem('usuario'))
} catch {
  usuario = null
}

const PESO_LABELS = { 1: 'Muy bajo', 2: 'Bajo', 3: 'Medio', 4: 'Alto', 5: 'Muy alto' }
const RELACIONES  = ['Hijo', 'Hija', 'Hermano', 'Hermana', 'Padre', 'Madre', 'Abuelo', 'Abuela', 'Otro']

// Reglas de validación del formulario de dependientes.
// Deben coincidir (o ser más estrictas) con las validaciones del backend.
const NOMBRE_MAX_LENGTH = 80
const OCUPACION_MAX_LENGTH = 80
const PESO_VALORES_VALIDOS = [1, 2, 3, 4, 5]
// Fecha máxima permitida: hoy (un dependiente no puede haber nacido en el futuro)
const HOY_ISO = (() => {
  const d = new Date()
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`
})()

const FORM_VACIO = { Nombre: '', Relacion: '', Ocupacion: '', Fecha_nacimiento: '', Peso_economico: '3' }

const inputCls  = 'mt-1.5 w-full rounded-xl border border-white/15 bg-white/[0.07] px-3.5 py-2.5 text-sm text-zinc-100 outline-none placeholder:text-zinc-500 focus:border-red-400/60 focus:ring-2 focus:ring-red-400/20'
const selectCls = inputCls
const labelCls  = 'mt-3.5 block text-[0.72rem] font-bold uppercase tracking-[0.06em] text-zinc-400'

const pesoColor = p => { if (p <= 1) return '#34d399'; if (p <= 2) return '#60a5fa'; if (p <= 3) return '#fbbf24'; if (p <= 4) return '#fb923c'; return '#f87171' }

const Dependientes = () => {
  const navigate = useNavigate()
  const location = useLocation()
  const token    = localStorage.getItem('token')
  const { mostrarToast } = useToast()
  const { revisarAhora } = useNotificaciones()

  const [dependientes, setDependientes] = useState([])
  const [mostrarModal, setMostrarModal] = useState(false)
  const [mostrarInfo, setMostrarInfo] = useState(false)
  const [editandoId,   setEditandoId]   = useState(null)
  const [formDatos,    setFormDatos]    = useState(FORM_VACIO)
  // evita doble envío del formulario (doble clic / doble submit)
  const [guardando, setGuardando] = useState(false)

  useEffect(() => {
    fetch(`${API_URL}/dependientes`, { headers: { Authorization: `Bearer ${token}` }, cache: 'no-store' })
      .then(res => res.json())
      .then(data => setDependientes(Array.isArray(data) ? data : []))
      .catch(err => console.error('Error cargando dependientes:', err))
  }, [])

  const handleChange = e => setFormDatos(prev => ({ ...prev, [e.target.name]: e.target.value }))

  const handleSubmit = async e => {
    e.preventDefault()

    const nombre = formDatos.Nombre.trim()
    const ocupacion = formDatos.Ocupacion.trim()
    const peso = parseInt(formDatos.Peso_economico)

    if (!nombre) return alert('El nombre es obligatorio')
    if (nombre.length > NOMBRE_MAX_LENGTH) {
      return alert(`El nombre no puede superar los ${NOMBRE_MAX_LENGTH} caracteres`)
    }
    if (ocupacion.length > OCUPACION_MAX_LENGTH) {
      return alert(`La ocupación no puede superar los ${OCUPACION_MAX_LENGTH} caracteres`)
    }
    if (!formDatos.Relacion) return alert('La relación es obligatoria')
    if (!formDatos.Fecha_nacimiento) return alert('La fecha de nacimiento es obligatoria')
    if (formDatos.Fecha_nacimiento > HOY_ISO) {
      return alert('La fecha de nacimiento no puede ser posterior a hoy')
    }
    if (!PESO_VALORES_VALIDOS.includes(peso)) {
      return alert('El peso económico no es válido')
    }
    if (guardando) return // evita doble envío si ya hay una petición en curso

    const payload = { ...formDatos, Nombre: nombre, Ocupacion: ocupacion, Peso_economico: peso, Fecha_nacimiento: formDatos.Fecha_nacimiento || null }

    setGuardando(true)
    try {
      if (editandoId) {
        const res = await fetch(`${API_URL}/dependientes/${editandoId}`, { method: 'PUT', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` }, body: JSON.stringify(payload) })
        if (res.ok) {
          mostrarToast('Dependiente actualizado correctamente')
          setDependientes(dependientes.map(d => d.id_dependientes === editandoId ? { ...payload, id_dependientes: editandoId } : d))
        }
        else { const data = await res.json(); alert(data.error || 'Error al actualizar') }
      } else {
        const res = await fetch(`${API_URL}/dependientes`, { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` }, body: JSON.stringify(payload) })
        const data = await res.json()
        if (res.ok) {
          mostrarToast('Dependiente registrado correctamente')
          setDependientes([...dependientes, { ...payload, id_dependientes: data.id_dependientes }])
        }
        else alert(data.error || 'Error al guardar')
      }
      cerrarModal()
    } catch (error) {
      alert('Error de conexión con el servidor')
    } finally {
      setGuardando(false)
    }
  }

  const handleEditar = d => {
    setFormDatos({ Nombre: d.Nombre, Relacion: d.Relacion, Ocupacion: d.Ocupacion || '', Fecha_nacimiento: d.Fecha_nacimiento ? d.Fecha_nacimiento.split('T')[0] : '', Peso_economico: String(d.Peso_economico ?? '3') })
    setEditandoId(d.id_dependientes)
    setMostrarModal(true)
  }

  const handleEliminar = async id => {
    if (!window.confirm('¿Estás seguro de que deseas eliminar este dependiente?')) return
    try {
      const res = await fetch(`${API_URL}/dependientes/${id}`, { method: 'DELETE', headers: { Authorization: `Bearer ${token}` } })
      if (res.ok) {
        mostrarToast('Dependiente eliminado correctamente')
        setDependientes(dependientes.filter(d => d.id_dependientes !== id))
      }
      else alert('Error al eliminar el dependiente')
    } catch (error) {
      alert('Error de conexión con el servidor')
    }
  }

  const abrirModal  = () => { setFormDatos(FORM_VACIO); setEditandoId(null); setMostrarModal(true) }
  const cerrarModal = () => { setMostrarModal(false); setEditandoId(null); setFormDatos(FORM_VACIO) }

  return (
    <div className="min-h-screen w-full flex flex-col text-white overflow-x-hidden"
      style={{ background: 'radial-gradient(ellipse at 30% 20%, #1e3a5f 10%, #0f172a 60%, #1a0f2e 100%)' }}>

      {/* HEADER */}
      <HeaderModulos section="dependientes" />

      <button
        type="button"
        onClick={() => setMostrarInfo(true)}
        aria-label="Acerca de este módulo"
        className="self-end mr-4 sm:mr-10 -mb-1 w-7 h-7 flex items-center justify-center rounded-full border border-white/10 text-white/50 text-xs hover:text-amber-400 hover:border-amber-400/50 transition-colors"
      >
        ℹ
      </button>

      {mostrarInfo && <InfoDependientes onClose={() => setMostrarInfo(false)} />}

      <hr className="my-1 border-none h-px"
        style={{ background: 'linear-gradient(to right, transparent, #fbbf24, transparent)' }} />

      {/* MAIN */}
      <main className="flex-1 flex flex-col w-full max-w-[1400px] mx-auto px-8 py-8 gap-6">

        {/* Bienvenida */}
        <div>
          <p className="text-[#a1a1aa] text-sm">Bienvenido de vuelta</p>

          <h2 className="text-xl sm:text-2xl font-extrabold text-white">{usuario?.nombre || 'Usuario'} <span>👋</span></h2>
        </div>

        {/* Stat + botón */}
        <article className="flex items-center justify-between px-8 py-6 rounded-2xl border border-white/10"
          style={{ background: 'radial-gradient(ellipse at left, rgba(99,102,241,0.35), rgba(79,70,229,0.04))' }}>
          <div>
            <p className="text-xs font-bold uppercase tracking-widest text-[#818cf8] mb-1">
              👩‍👧‍👦 Total Dependientes
            </p>
            <p className="text-4xl font-black text-white">{dependientes.length}</p>
          </div>
          <button
            onClick={abrirModal}
            className="px-5 py-2.5 rounded-xl font-bold text-sm cursor-pointer border-none text-white hover:-translate-y-px transition-all duration-300"
            style={{ background: 'linear-gradient(135deg, #818cf8, #6366f1)' }}>
            ➕ Agregar Dependiente
          </button>
        </article>

        {/* Cards */}
        <section className="w-full rounded-2xl border border-white/10 p-6 shadow-[0_8px_32px_rgba(0,0,0,0.35)]"
          style={{ background: 'rgba(255,255,255,0.04)', backdropFilter: 'blur(16px)' }}>

          <div className="flex items-center justify-between mb-5">
            <h3 className="text-base font-extrabold text-[#fbbf24]">📋 Módulo de Dependientes</h3>
          </div>

          {dependientes.length === 0 ? (
            <p className="text-zinc-500 italic text-sm">
              No hay dependientes registrados. Agrega tu primer dependiente para comenzar.
            </p>
          ) : (
            <div className="grid gap-4" style={{ gridTemplateColumns: 'repeat(auto-fill, minmax(240px, 1fr))' }}>
              {dependientes.map(dep => (
                <div key={dep.id_dependientes}
                  className="rounded-2xl p-[18px] border border-white/[0.09] transition-all duration-200 hover:-translate-y-1 hover:shadow-[0_8px_24px_rgba(0,0,0,0.3)]"
                  style={{ background: 'rgba(255,255,255,0.05)' }}>

                  <div className="flex flex-col gap-1.5 mb-3.5">
                    <p className="text-base font-extrabold text-[#f4f4f5]">{dep.Nombre}</p>
                    <p className="text-xs text-[#a1a1aa]">
                      {dep.Relacion}{dep.Ocupacion ? ` · ${dep.Ocupacion}` : ''}
                    </p>
                    {dep.Fecha_nacimiento && (
                      <p className="text-[0.72rem] text-zinc-500">
                        Nac: {dep.Fecha_nacimiento.split('T')[0]}
                      </p>
                    )}
                    <span
                      className="inline-block mt-1 px-2.5 py-1 rounded-full text-[0.7rem] font-bold"
                      style={{
                        background: `${pesoColor(dep.Peso_economico)}22`,
                        color: pesoColor(dep.Peso_economico),
                        border: `1px solid ${pesoColor(dep.Peso_economico)}44`,
                      }}>
                      Peso económico: {PESO_LABELS[dep.Peso_economico] ?? 'N/A'}
                    </span>
                  </div>

                  <div className="flex gap-2">
                    <button
                      onClick={() => handleEditar(dep)}
                      className="flex-1 py-1.5 rounded-lg text-xs font-bold cursor-pointer border border-indigo-400/50 bg-indigo-400/10 text-[#818cf8] hover:bg-indigo-400/[0.22] transition-colors duration-150">
                      Editar
                    </button>
                    <button
                      onClick={() => handleEliminar(dep.id_dependientes)}
                      className="flex-1 py-1.5 rounded-lg text-xs font-bold cursor-pointer border border-red-400/50 bg-red-400/10 text-[#f87171] hover:bg-red-400/[0.22] transition-colors duration-150">
                      Eliminar
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </section>
      </main>

      {/* FOOTER */}
      <footer className="w-full py-6 text-center text-zinc-700 text-[0.7rem] font-mono">
        <p>© <strong className="text-[#fbbf24]">2026 Ahorrapp</strong>. Todos los derechos reservados.</p>
      </footer>

      {/* MODAL */}
      {mostrarModal && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-4 bg-black/65 backdrop-blur-md">
          <div className="w-full max-w-[480px] rounded-[20px] p-7 border border-white/[0.12] shadow-[0_24px_60px_rgba(0,0,0,0.6)] max-h-[90vh] overflow-y-auto"
            style={{ background: 'rgba(15,23,42,0.92)' }}>

            <h4 className="text-lg font-extrabold text-amber-400 mb-1">{editandoId ? '✏️ Editar Dependiente' : '➕ Agregar Dependiente'}</h4>

            <form onSubmit={handleSubmit} className="flex flex-col gap-1">

              <label className={labelCls}>Nombre *</label>
              <input className={inputCls} type="text" name="Nombre" value={formDatos.Nombre} onChange={handleChange} required maxLength={NOMBRE_MAX_LENGTH} disabled={guardando} placeholder="Nombre del dependiente" />


              <label className={labelCls}>Relación *</label>
              <select className={`${selectCls} [&>option]:bg-zinc-800`} style={{ colorScheme: 'dark' }} name="Relacion" value={formDatos.Relacion} onChange={handleChange} required disabled={guardando}>
                <option value="" className="text-zinc-500">Selecciona una relación</option>
                {RELACIONES.map(r => (
                  <option key={r} value={r}>{r}</option>
                ))}
              </select>
              

              <label className={labelCls}>Ocupación</label>
              <input className={inputCls} type="text" name="Ocupacion" value={formDatos.Ocupacion} onChange={handleChange} maxLength={OCUPACION_MAX_LENGTH} disabled={guardando} placeholder="Ocupación del dependiente" />

              <label className={labelCls}>Fecha de Nacimiento *</label>
              <input className={inputCls} type="date" name="Fecha_nacimiento" value={formDatos.Fecha_nacimiento} onChange={handleChange} required max={HOY_ISO} disabled={guardando} />

              <label className={labelCls}>Peso Económico</label>
              {/* <select className= name="Relacion" value={formDatos.Relacion} onChange={handleChange} required disabled={guardando}> */}
              <select className={`${selectCls} [&>option]:bg-zinc-800`} style={{ colorScheme: 'dark' }} name="Peso_economico" value={formDatos.Peso_economico} onChange={handleChange} required disabled={guardando}>
                {PESO_VALORES_VALIDOS.map(p => (
                  <option key={p} value={p}>{p} - {PESO_LABELS[p]}</option>
                ))}
              </select>

              <div className="mt-6 flex gap-2.5">
                <button
                  type="submit"
                  disabled={guardando}
                  className="flex-1 py-2.5 rounded-xl text-sm font-bold cursor-pointer border-none text-white disabled:opacity-50"
                  style={{ background: 'linear-gradient(135deg, #818cf8, #6366f1)' }}>
                  {guardando ? 'Guardando...' : 'Guardar'}
                </button>
                <button
                  type="button"
                  onClick={cerrarModal}
                  disabled={guardando}
                  className="flex-1 py-2.5 rounded-xl text-sm font-bold cursor-pointer bg-transparent text-[#a1a1aa] border border-white/15 hover:bg-white/[0.07] transition-colors duration-150 disabled:opacity-50">
                  Cancelar
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  )
}

export default Dependientes

import { useState, useEffect, useMemo } from 'react'
import { useNavigate } from 'react-router-dom'
import { getCategorias, getDependientes } from '../services/api'
import ModalNuevoMovimiento from '../components/Modalnuevomovimiento'
import HeaderModulos from '../components/HeaderModulos'
import { useToast } from '../context/ToastContext'
import { useNotificaciones } from '../context/NotificacionesContext'

// const API = 'http://localhost:3000/api/movimientos'
const API = 'https://david-ekcn.onrender.com/api/movimientos'

const fmt      = (n) => `$${Number(n).toLocaleString('es-CO')}`
const fmtFecha = (f) => {
  if (!f) return '—'
  const [y, m, d] = f.slice(0, 10).split('-')
  return `${d}/${m}/${y}`
}

const inputCls = 'mt-1.5 w-full rounded-xl border border-white/15 bg-white/[0.07] px-3.5 py-2.5 text-sm text-zinc-100 outline-none placeholder:text-zinc-500 focus:border-red-400/60 focus:ring-2 focus:ring-red-400/20'
const selectCls = inputCls 
const labelCls = 'mt-3.5 block text-[0.72rem] font-bold uppercase tracking-[0.06em] text-zinc-400'

export default function ModulosGastos() {
  const navigate = useNavigate()
  const usuario  = useMemo(() => { try { return JSON.parse(localStorage.getItem('usuario')) } catch { return null } }, [])
  const { mostrarToast } = useToast()
  const { revisarAhora } = useNotificaciones()

  const [gastos,      setGastos]      = useState([])
  const [cargando,    setCargando]    = useState(true)
  const [modalNuevo,  setModalNuevo]  = useState(false)
  const [categorias,  setCategorias]  = useState([])
  const [dependientes,setDependientes]= useState([])
  const [modalEditar, setModalEditar] = useState(null)
  const [confirmarId, setConfirmarId] = useState(null)
  const [guardando,   setGuardando]   = useState(false)
  const [eliminando,  setEliminando]  = useState(false)
  const [errorModal,  setErrorModal]  = useState(null)

  const cargar = () => {
    setCargando(true)
    const token = localStorage.getItem('token')
    fetch(`${API}/gastos`, { headers: { Authorization: `Bearer ${token}` }, cache: 'no-store' })
      .then(r => r.json())
      .then(d => { if (Array.isArray(d)) setGastos(d) })
      .catch(() => {})
      .finally(() => setCargando(false))
  }

  useEffect(() => {
    cargar()
    getCategorias().then(d => { if (Array.isArray(d)) setCategorias(d) }).catch(() => {})
    getDependientes().then(d => { if (Array.isArray(d)) setDependientes(d) }).catch(() => {})
  }, [])

  const total = useMemo(() => gastos.reduce((a, g) => a + Number(g.monto || 0), 0), [gastos])

  const abrirEditar = (g) => {
    setErrorModal(null)
    setModalEditar({
      id: g.id, monto: String(g.monto),
      descripcion: g.descripcion || '',
      fecha_registro: g.fecha ? g.fecha.slice(0, 10) : '',
      id_categoria: g.id_categoria || '',
      id_dependientes: g.id_dependientes || '',
    })
  }

  const handleChange = (e) => setModalEditar(p => ({ ...p, [e.target.name]: e.target.value }))

  const guardar = async () => {
    setErrorModal(null)
    if (!modalEditar.monto || isNaN(modalEditar.monto) || Number(modalEditar.monto) <= 49)
      return setErrorModal('El monto debe ser de al menos 50')
    setGuardando(true)
    const token = localStorage.getItem('token')
    try {
      const res  = await fetch(`${API}/gastos/${modalEditar.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify({
          monto: Number(modalEditar.monto),
          descripcion: modalEditar.descripcion || null,
          fecha_registro: modalEditar.fecha_registro || null,
          id_categoria: modalEditar.id_categoria || null,
          id_dependientes: modalEditar.id_dependientes || null,
        }),
      })
      const data = await res.json()
      if (res.ok) {
        mostrarToast('Gasto actualizado correctamente')
        revisarAhora()
        setModalEditar(null)
        cargar()
      }
      else setErrorModal(data.mensaje || 'Error al guardar')
    } catch { setErrorModal('Error al conectar con el servidor') }
    finally { setGuardando(false) }
  }

  const eliminar = async () => {
    setEliminando(true)
    const token = localStorage.getItem('token')
    try {
      const res = await fetch(`${API}/gastos/${confirmarId}`, { method: 'DELETE', headers: { Authorization: `Bearer ${token}` } })
      if (res.ok) {
        mostrarToast('Gasto eliminado correctamente')
        revisarAhora()
        setConfirmarId(null)
        cargar()
      }
    } catch {}
    finally { setEliminando(false) }
  }

  const nombreDep = (id) => {
    if (!id) return null
    const dep = dependientes.find(d => String(d.id_dependientes) === String(id))
    return dep?.Nombre || null
  }

  return (
    <div className="min-h-screen w-full flex flex-col text-white overflow-x-hidden"
      style={{ background: 'radial-gradient(ellipse at 30% 20%, #1e3a5f 10%, #0f172a 60%, #1a0f2e 100%)' }}>

      <HeaderModulos section="Gastos" />
      <hr className="my-1 h-px border-0 bg-gradient-to-r from-transparent via-amber-400 to-transparent" />

      <main className="flex-1 flex flex-col w-full max-w-[1400px] mx-auto px-4 py-5 sm:px-6 sm:py-6 md:p-8 gap-6">

        <div>
          <p className="text-sm text-zinc-400">Bienvenido de vuelta</p>
          <h2 className="text-xl sm:text-2xl font-extrabold text-white">{usuario?.nombre || 'Usuario'} <span>👋</span></h2>
        </div>

        {/* Stat card */}
        <article className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 px-5 sm:px-8 py-5 sm:py-6 rounded-2xl border border-white/10"
          style={{ background: 'radial-gradient(ellipse at left, rgba(239,68,68,0.35), rgba(220,38,38,0.04))' }}>
          <div>
            <p className="text-xs font-bold uppercase tracking-widest text-red-400 mb-1">💸 Total Gastos</p>
            <p className="text-3xl sm:text-4xl font-black text-white">{fmt(total)}</p>
            <p className="text-xs text-zinc-500 mt-1">{gastos.length} registro{gastos.length !== 1 ? 's' : ''} en total</p>
          </div>
          <button onClick={() => setModalNuevo(true)}
            className="w-full sm:w-auto px-5 py-3 rounded-xl font-bold text-sm text-white transition-all duration-300 hover:-translate-y-px"
            style={{ background: 'linear-gradient(135deg, #f87171, #ef4444)' }}>
            ➕ Agregar Gasto
          </button>
        </article>

        {/* Tabla */}
        <section className="w-full rounded-2xl border border-white/10 overflow-hidden shadow-[0_8px_32px_rgba(0,0,0,0.35)]"
          style={{ background: 'rgba(255,255,255,0.04)', backdropFilter: 'blur(16px)' }}>

          <div className="flex items-center justify-between px-5 sm:px-7 py-4 sm:py-5 border-b border-white/[0.08]">
            <h3 className="text-base font-extrabold text-amber-400">📋 Módulo de Gastos</h3>
            <span className="text-xs text-zinc-600">{gastos.length} registro{gastos.length !== 1 ? 's' : ''}</span>
          </div>

          <div className="p-4 sm:p-5">
            {cargando ? (
              <p className="py-8 text-center text-sm italic text-zinc-500 animate-pulse">⏳ Cargando gastos...</p>
            ) : gastos.length === 0 ? (
              <div className="py-12 flex flex-col items-center gap-3 text-center">
                <span className="text-4xl opacity-30">💸</span>
                <p className="text-zinc-400 text-sm">No hay gastos registrados aún.</p>
                <button onClick={() => setModalNuevo(true)}
                  className="mt-2 px-5 py-2.5 rounded-xl text-sm font-bold text-white"
                  style={{ background: 'linear-gradient(135deg, #f87171, #ef4444)' }}>
                  Registrar primer gasto
                </button>
              </div>
            ) : (
              <>
                {/* Mobile cards */}
                <div className="flex flex-col gap-3 md:hidden">
                  {gastos.map(g => (
                    <article key={g.id} className="rounded-xl border border-white/10 bg-white/[0.03] p-4">
                      <div className="flex items-start justify-between gap-3">
                        <div className="min-w-0 flex-1">
                          <p className="font-bold text-white truncate">{g.descripcion || 'Sin descripción'}</p>
                          <p className="text-xs text-zinc-500 mt-0.5">{fmtFecha(g.fecha)}</p>
                          {g.categoria && <p className="text-xs text-zinc-500 mt-1">📂 {g.categoria}</p>}
                          {nombreDep(g.id_dependientes) && (
                            <p className="text-xs text-blue-400 mt-1">👤 {nombreDep(g.id_dependientes)}</p>
                          )}
                        </div>
                        <p className="shrink-0 text-base font-black text-red-400">{fmt(g.monto)}</p>
                      </div>
                      <div className="mt-3 grid grid-cols-2 gap-2">
                        <button onClick={() => abrirEditar(g)} className="rounded-lg border border-blue-400/50 bg-blue-400/10 py-2 text-xs font-bold text-blue-400 hover:bg-blue-400/20 transition-colors">Editar</button>
                        <button onClick={() => setConfirmarId(g.id)} className="rounded-lg border border-red-400/50 bg-red-400/10 py-2 text-xs font-bold text-red-400 hover:bg-red-400/20 transition-colors">Eliminar</button>
                      </div>
                    </article>
                  ))}
                </div>

                {/* Desktop table */}
                <div className="hidden md:block overflow-x-auto">
                  <table className="w-full min-w-[850px] border-collapse text-left">
                    <thead>
                      <tr className="border-b border-white/10">
                        {['Fecha', 'Descripción', 'Categoría', 'Dependiente', 'Monto', 'Acciones'].map(col => (
                          <th key={col} className="px-4 py-3 text-xs font-bold uppercase tracking-wider text-zinc-500">{col}</th>
                        ))}
                      </tr>
                    </thead>
                    <tbody>
                      {gastos.map(g => (
                        <tr key={g.id} className="border-b border-white/5 hover:bg-white/[0.04] transition-colors">
                          <td className="px-4 py-3 text-sm text-zinc-300">{fmtFecha(g.fecha)}</td>
                          <td className="px-4 py-3 text-sm text-zinc-300 max-w-[200px] truncate">{g.descripcion || '—'}</td>
                          <td className="px-4 py-3 text-sm text-zinc-300">{g.categoria || '—'}</td>
                          <td className="px-4 py-3 text-sm text-blue-400">{nombreDep(g.id_dependientes) || '—'}</td>
                          <td className="px-4 py-3 text-sm font-extrabold text-red-400">{fmt(g.monto)}</td>
                          <td className="px-4 py-3">
                            <div className="flex gap-2">
                              <button onClick={() => abrirEditar(g)} className="px-3.5 py-1.5 rounded-lg text-xs font-bold border border-blue-400/50 bg-blue-400/10 text-blue-400 hover:bg-blue-400/20 transition-colors">Editar</button>
                              <button onClick={() => setConfirmarId(g.id)} className="px-3.5 py-1.5 rounded-lg text-xs font-bold border border-red-400/50 bg-red-400/10 text-red-400 hover:bg-red-400/20 transition-colors">Eliminar</button>
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </>
            )}
          </div>
        </section>
      </main>

      <footer className="w-full px-4 py-6 text-center font-mono text-[0.7rem] text-zinc-600">
        <p>© <strong className="text-amber-400">2026 Ahorrapp</strong>. Todos los derechos reservados.</p>
      </footer>

      {/* Modal Editar */}
      {modalEditar && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-4 bg-black/65 backdrop-blur-md">
          <div className="w-full max-w-[460px] rounded-[20px] p-7 border border-white/[0.12] shadow-[0_24px_60px_rgba(0,0,0,0.6)] max-h-[90vh] overflow-y-auto"
            style={{ background: 'rgba(15,23,42,0.95)' }}>
            <h4 className="text-lg font-extrabold text-red-400 mb-1">✏️ Editar Gasto</h4>
            <p className="text-xs text-zinc-500 mb-2">Modifica los campos que necesites y guarda.</p>

            <label className={labelCls}>Monto *</label>
            <input className={inputCls} type="number" name="monto" min="50" step="0.01" value={modalEditar.monto} onChange={handleChange} />

            <label className={labelCls}>Descripción</label>
            <input className={inputCls} type="text" name="descripcion" placeholder="Descripción opcional" value={modalEditar.descripcion} onChange={handleChange} />

            <label className={labelCls}>Categoría</label>
            <select
              className={selectCls}
              style={{ colorScheme: 'dark' }}
              name="id_categoria"
              value={modalEditar.id_categoria}
              onChange={handleChange}
            >
              <option value="" style={{ backgroundColor: '#1f2937', color: '#f4f4f5' }}>Sin categoría</option>
              {categorias.filter(c => c.activa == 1).map(c => (
                <option key={c.id} value={c.id} style={{ backgroundColor: '#1f2937', color: '#f4f4f5' }}>
                  {c.nombre}
                </option>
              ))}
            </select>

            <label className={labelCls}>Dependiente</label>
            <select
              className={selectCls}
              style={{ colorScheme: 'dark' }}
              name="id_dependientes"
              value={modalEditar.id_dependientes}
              onChange={handleChange}
            >
              <option value="" style={{ backgroundColor: '#1f2937', color: '#f4f4f5' }}>Ninguno (gasto propio)</option>
              {dependientes.map(d => (
                <option key={d.id_dependientes} value={d.id_dependientes} style={{ backgroundColor: '#1f2937', color: '#f4f4f5' }}>
                  {d.Nombre}
                </option>
              ))}
            </select> 

            <label className={labelCls}>Fecha</label>
            <input className={inputCls} type="date" name="fecha_registro" value={modalEditar.fecha_registro} onChange={handleChange} />

            {errorModal && <p className="mt-3 p-[10px_14px] rounded-[10px] bg-red-400/[0.12] border border-red-400/35 text-red-400 text-[0.8rem] font-semibold">{errorModal}</p>}

            <div className="mt-6 flex justify-end gap-2.5">
              <button onClick={() => setModalEditar(null)} className="px-5 py-2.5 rounded-[10px] text-sm font-bold bg-transparent text-zinc-400 border border-white/[0.15] hover:bg-white/[0.07] transition-colors">Cancelar</button>
              <button onClick={guardar} disabled={guardando} className="px-5 py-2.5 rounded-[10px] text-sm font-bold text-white disabled:opacity-50 disabled:cursor-not-allowed transition-opacity"
                style={{ background: guardando ? 'rgba(248,113,113,0.4)' : 'linear-gradient(135deg, #f87171, #ef4444)' }}>
                {guardando ? 'Guardando...' : 'Guardar cambios'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Modal Eliminar */}
      {confirmarId && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-4 bg-black/65 backdrop-blur-md">
          <div className="w-full max-w-[380px] rounded-[20px] p-7 border border-red-400/25 shadow-[0_24px_60px_rgba(0,0,0,0.6)]"
            style={{ background: 'rgba(15,23,42,0.95)' }}>
            <h4 className="text-lg font-extrabold text-red-400 mb-2">🗑️ ¿Eliminar gasto?</h4>
            <p className="text-sm text-zinc-400">Esta acción no se puede deshacer.</p>
            <div className="mt-6 flex justify-end gap-2.5">
              <button onClick={() => setConfirmarId(null)} className="px-5 py-2.5 rounded-[10px] text-sm font-bold bg-transparent text-zinc-400 border border-white/[0.15] hover:bg-white/[0.07] transition-colors">Cancelar</button>
              <button onClick={eliminar} disabled={eliminando} className="px-5 py-2.5 rounded-[10px] text-sm font-bold text-white disabled:opacity-50 disabled:cursor-not-allowed transition-opacity"
                style={{ background: eliminando ? 'rgba(248,113,113,0.4)' : 'linear-gradient(135deg, #f87171, #ef4444)' }}>
                {eliminando ? 'Eliminando...' : 'Eliminar'}
              </button>
            </div>
          </div>
        </div>
      )}

      {modalNuevo && (
        <ModalNuevoMovimiento
          subtipo="Gasto"
          onCerrar={() => setModalNuevo(false)}
          onGuardado={() => cargar()}
        />
      )}
    </div>
  )
}

import { useState, useEffect, useMemo } from 'react'
